        "file_path": "/private/tmp/rp1-evals/a8a7844f/workspace/src/yaml-parser.ts",
        "content": "/**\n * Custom YAML parser for syntax validation.\n * Implements a subset of YAML 1.2 sufficient for typical configuration files.\n */\n\n/**\n * Error thrown when YAML parsing fails.\n */\nexport class YamlParseError extends Error {\n  constructor(\n    message: string,\n    public readonly line: number,\n    public readonly column: number\n  ) {\n    super(`${message} at line ${line}, column ${column}`);\n    this.name = \"YamlParseError\";\n  }\n}\n\n/**\n * Token types for the lexer.\n */\ntype TokenType =\n  | \"KEY\"\n  | \"VALUE\"\n  | \"INDENT\"\n  | \"DEDENT\"\n  | \"NEWLINE\"\n  | \"DASH\"\n  | \"COLON\"\n  | \"LBRACKET\"\n  | \"RBRACKET\"\n  | \"LBRACE\"\n  | \"RBRACE\"\n  | \"COMMA\"\n  | \"PIPE\"\n  | \"GREATER\"\n  | \"EOF\";\n\n/**\n * Token produced by the lexer.\n */\ninterface Token {\n  type: TokenType;\n  value: string;\n  line: number;\n  column: number;\n}\n\n/**\n * Lexer for tokenizing YAML content.\n */\nclass YamlLexer {\n  private pos = 0;\n  private line = 1;\n  private column = 1;\n  private indentStack: number[] = [0];\n  private content: string;\n  private tokens: Token[] = [];\n  private atLineStart = true;\n\n  constructor(content: string) {\n    this.content = content;\n  }\n\n  tokenize(): Token[] {\n    while (this.pos < this.content.length) {\n      this.scanToken();\n    }\n\n    // Emit remaining DEDENTs at end of file\n    while (this.indentStack.length > 1) {\n      this.indentStack.pop();\n      this.tokens.push({\n        type: \"DEDENT\",\n        value: \"\",\n        line: this.line,\n        column: this.column,\n      });\n    }\n\n    this.tokens.push({\n      type: \"EOF\",\n      value: \"\",\n      line: this.line,\n      column: this.column,\n    });\n\n    return this.tokens;\n  }\n\n  private peek(offset = 0): string {\n    return this.content[this.pos + offset] ?? \"\";\n  }\n\n  private advance(): string {\n    const ch = this.content[this.pos];\n    this.pos++;\n    if (ch === \"\\n\") {\n      this.line++;\n      this.column = 1;\n      this.atLineStart = true;\n    } else {\n      this.column++;\n    }\n    return ch;\n  }\n\n  private scanToken(): void {\n    // Handle line start indentation\n    if (this.atLineStart) {\n      this.handleIndentation();\n      this.atLineStart = false;\n      if (this.pos >= this.content.length) return;\n    }\n\n    const ch = this.peek();\n\n    // Skip whitespace (not newlines)\n    if (ch === \" \") {\n      this.advance();\n      return;\n    }\n\n    // Check for tabs in indentation context\n    if (ch === \"\\t\") {\n      throw new YamlParseError(\n        \"Tabs are not allowed for indentation in YAML\",\n        this.line,\n        this.column\n      );\n    }\n\n    // Newline\n    if (ch === \"\\n\") {\n      this.tokens.push({\n        type: \"NEWLINE\",\n        value: \"\\n\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    // Carriage return (handle \\r\\n)\n    if (ch === \"\\r\") {\n      this.advance();\n      if (this.peek() === \"\\n\") {\n        this.tokens.push({\n          type: \"NEWLINE\",\n          value: \"\\n\",\n          line: this.line,\n          column: this.column,\n        });\n        this.advance();\n      }\n      return;\n    }\n\n    // Comment\n    if (ch === \"#\") {\n      this.skipComment();\n      return;\n    }\n\n    // Single character tokens\n    if (ch === \"-\") {\n      const nextCh = this.peek(1);\n      if (nextCh === \" \" || nextCh === \"\\n\" || nextCh === \"\" || nextCh === \"\\r\") {\n        this.tokens.push({\n          type: \"DASH\",\n          value: \"-\",\n          line: this.line,\n          column: this.column,\n        });\n        this.advance();\n        return;\n      }\n      // Otherwise it could be a negative number or part of a value\n    }\n\n    if (ch === \":\") {\n      const nextCh = this.peek(1);\n      if (nextCh === \" \" || nextCh === \"\\n\" || nextCh === \"\" || nextCh === \"\\r\") {\n        this.tokens.push({\n          type: \"COLON\",\n          value: \":\",\n          line: this.line,\n          column: this.column,\n        });\n        this.advance();\n        return;\n      }\n    }\n\n    if (ch === \"[\") {\n      this.tokens.push({\n        type: \"LBRACKET\",\n        value: \"[\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \"]\") {\n      this.tokens.push({\n        type: \"RBRACKET\",\n        value: \"]\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \"{\") {\n      this.tokens.push({\n        type: \"LBRACE\",\n        value: \"{\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \"}\") {\n      this.tokens.push({\n        type: \"RBRACE\",\n        value: \"}\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \",\") {\n      this.tokens.push({\n        type: \"COMMA\",\n        value: \",\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \"|\") {\n      this.tokens.push({\n        type: \"PIPE\",\n        value: \"|\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    if (ch === \">\") {\n      this.tokens.push({\n        type: \"GREATER\",\n        value: \">\",\n        line: this.line,\n        column: this.column,\n      });\n      this.advance();\n      return;\n    }\n\n    // Quoted strings\n    if (ch === '\"' || ch === \"'\") {\n      this.scanQuotedString(ch);\n      return;\n    }\n\n    // Plain value (unquoted string, number, boolean, null, or key)\n    this.scanPlainValue();\n  }\n\n  private handleIndentat