        "content": "/**\n * CLI entry point for YAML validation.\n * Validates YAML file syntax and reports results with appropriate exit codes.\n */\n\nimport { parseYaml, YamlParseError } from \"./yaml-parser\";\n\nfunction printUsage(): void {\n  console.log(\"Usage: bun run validate <file.yaml>\");\n  console.log(\"Validates YAML file syntax.\");\n}\n\nasync function readFile(filePath: string): Promise<string> {\n  const file = Bun.file(filePath);\n  const exists = await file.exists();\n\n  if (!exists) {\n    throw new Error(`File not found: ${filePath}`);\n  }\n\n  try {\n    return await file.text();\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    throw new Error(`Cannot read file: ${filePath}\\n${message}`);\n  }\n}\n\nfunction handleError(error: unknown, filePath: string): void {\n  if (error instanceof Error) {\n    if (error.message.startsWith(\"File not found:\")) {\n      console.error(`Error: ${error.message}`);\n    } else if (error.message.startsWith(\"Cannot read file:\")) {\n      console.error(`Error: ${error.message}`);\n    } else if (error instanceof YamlParseError) {\n      console.log(`Invalid YAML: ${filePath}`);\n      console.log(`Error: ${error.message}`);\n    } else {\n      console.log(`Invalid YAML: ${filePath}`);\n      console.log(`Error: ${error.message}`);\n    }\n  } else {\n    console.log(`Invalid YAML: ${filePath}`);\n    console.log(`Error: ${String(error)}`);\n  }\n}\n\nasync function main(): Promise<void> {\n  const filePath = process.argv[2];\n\n  if (!filePath) {\n    printUsage();\n    process.exit(1);\n  }\n\n  try {\n    const content = await readFile(filePath);\n    parseYaml(content);\n    console.log(`Valid YAML: ${filePath}`);\n    process.exit(0);\n  } catch (error) {\n    handleError(error, filePath);\n    process.exit(1);\n  }\n}\n\nmain();\n"
