        "content": "import { describe, expect, test } from \"bun:test\";\nimport { parseYaml, YamlParseError } from \"./yaml-parser\";\n\ndescribe(\"yaml-parser\", () => {\n  describe(\"empty document\", () => {\n    test(\"returns null for empty string\", () => {\n      expect(parseYaml(\"\")).toBe(null);\n    });\n\n    test(\"returns null for whitespace only\", () => {\n      expect(parseYaml(\"   \\n  \\n\")).toBe(null);\n    });\n  });\n\n  describe(\"simple key-value pairs\", () => {\n    test(\"parses simple key-value\", () => {\n      expect(parseYaml(\"key: value\")).toEqual({ key: \"value\" });\n    });\n\n    test(\"parses multiple key-value pairs\", () => {\n      expect(parseYaml(\"name: John\\nage: 30\")).toEqual({\n        name: \"John\",\n        age: 30,\n      });\n    });\n  });\n\n  describe(\"nested objects\", () => {\n    test(\"parses nested object via indentation\", () => {\n      const yaml = `a:\n  b: c`;\n      expect(parseYaml(yaml)).toEqual({ a: { b: \"c\" } });\n    });\n\n    test(\"parses deeply nested objects\", () => {\n      const yaml = `level1:\n  level2:\n    level3: value`;\n      expect(parseYaml(yaml)).toEqual({\n        level1: { level2: { level3: \"value\" } },\n      });\n    });\n  });\n\n  describe(\"block arrays\", () => {\n    test(\"parses block array with dash syntax\", () => {\n      const yaml = `- a\n- b`;\n      expect(parseYaml(yaml)).toEqual([\"a\", \"b\"]);\n    });\n\n    test(\"parses array with numeric values\", () => {\n      const yaml = `- 1\n- 2\n- 3`;\n      expect(parseYaml(yaml)).toEqual([1, 2, 3]);\n    });\n\n    test(\"parses array nested in object\", () => {\n      const yaml = `items:\n  - first\n  - second`;\n      expect(parseYaml(yaml)).toEqual({ items: [\"first\", \"second\"] });\n    });\n  });\n\n  describe(\"inline arrays\", () => {\n    test(\"parses inline array with numbers\", () => {\n      expect(parseYaml(\"[1, 2, 3]\")).toEqual([1, 2, 3]);\n    });\n\n    test(\"parses inline array with strings\", () => {\n      expect(parseYaml(\"[a, b, c]\")).toEqual([\"a\", \"b\", \"c\"]);\n    });\n\n    test(\"parses inline array in object\", () => {\n      expect(parseYaml(\"items: [1, 2, 3]\")).toEqual({ items: [1, 2, 3] });\n    });\n\n    test(\"parses empty inline array\", () => {\n      expect(parseYaml(\"[]\")).toEqual([]);\n    });\n  });\n\n  describe(\"inline objects\", () => {\n    test(\"parses inline object\", () => {\n      expect(parseYaml(\"{a: 1, b: 2}\")).toEqual({ a: 1, b: 2 });\n    });\n\n    test(\"parses inline object in object\", () => {\n      expect(parseYaml(\"data: {x: 10, y: 20}\")).toEqual({\n        data: { x: 10, y: 20 },\n      });\n    });\n\n    test(\"parses empty inline object\", () => {\n      expect(parseYaml(\"{}\")).toEqual({});\n    });\n  });\n\n  describe(\"numbers\", () => {\n    test(\"parses integer\", () => {\n      expect(parseYaml(\"count: 42\")).toEqual({ count: 42 });\n    });\n\n    test(\"parses negative integer\", () => {\n      expect(parseYaml(\"value: -7\")).toEqual({ value: -7 });\n    });\n\n    test(\"parses float\", () => {\n      expect(parseYaml(\"pi: 3.14\")).toEqual({ pi: 3.14 });\n    });\n\n    test(\"parses negative float\", () => {\n      expect(parseYaml(\"temp: -2.5\")).toEqual({ temp: -2.5 });\n    });\n  });\n\n  describe(\"booleans\", () => {\n    test(\"parses true\", () => {\n      expect(parseYaml(\"flag: true\")).toEqual({ flag: true });\n    });\n\n    test(\"parses false\", () => {\n      expect(parseYaml(\"flag: false\")).toEqual({ flag: false });\n    });\n\n    test(\"parses yes as true\", () => {\n      expect(parseYaml(\"enabled: yes\")).toEqual({ enabled: true });\n    });\n\n    test(\"parses no as false\", () => {\n      expect(parseYaml(\"enabled: no\")).toEqual({ enabled: false });\n    });\n  });\n\n  describe(\"null\", () => {\n    test(\"parses null keyword\", () => {\n      expect(parseYaml(\"value: null\")).toEqual({ value: null });\n    });\n\n    test(\"parses tilde as null\", () => {\n      expect(parseYaml(\"value: ~\")).toEqual({ value: null });\n    });\n\n    test(\"parses empty value as null\", () => {\n      expect(parseYaml(\"value:\")).toEqual({ value: null });\n    });\n  });\n\n  describe(\"quoted strings\", () => {\n    test(\"parses double-quoted string\", () => {\n      expect(parseYaml('name: \"hello\"')).toEqual({ name: \"hello\" });\n    });\n\n    test(\"parses single-quoted string\", () => {\n      expect(parseYaml(\"name: 'world'\")).toEqual({ name: \"world\" });\n    });\n\n    test(\"parses string with escape sequences\", () => {\n      expect(parseYaml('text: \"hello\\\\nworld\"')).toEqual({\n        text: \"hello\\nworld\",\n      });\n    });\n\n    test(\"parses string that looks like number when quoted\", () => {\n      expect(parseYaml('code: \"42\"')).toEqual({ code: \"42\" });\n    });\n  });\n\n  describe(\"multiline strings\", () => {\n    test(\"parses literal block scalar with pipe\", () => {\n      const yaml = `text: |\n  line1\n  line2`;\n      expect(parseYaml(yaml)).toEqual({ text: \"line1\\nline2\" });\n    });\n\n    test(\"parses folded block scalar with greater\", () => {\n      const yaml = `text: >\n  line1\n  line2`;\n      expect(parseYaml(yaml)).toEqual({ text: \"line1 line2\" });\n    });\n  });\n\n  describe(\"comments\", () => {\n    test(\"ignores comment at start\", () => {\n      const yaml = `# comment\nkey: value`;\n      expect(parseYaml(yaml)).toEqual({ key: \"value\" });\n    });\n\n    test(\"ignores inline comment\", () => {\n      expect(parseYaml(\"key: value # this is a comment\")).toEqual({\n        key: \"value\",\n      });\n    });\n\n    test(\"ignores comment-only lines\", () => {\n      const yaml = `a: 1\n# middle comment\nb: 2`;\n      expect(parseYaml(yaml)).toEqual({ a: 1, b: 2 });\n    });\n  });\n\n  describe(\"error cases\", () => {\n    test(\"throws YamlParseError for invalid indentation\", () => {\n      const yaml = `a:\n   b: c\n  d: e`;\n      expect(() => parseYaml(yaml)).toThrow(YamlParseError);\n    });\n\n    test(\"throws YamlParseError for tabs in indentation\", () => {\n      const yaml = \"a:\\n\\tb: c\";\n      expect(() => parseYaml(yaml)).toThrow(YamlParseError);\n      expect(() => parseYaml(yaml)).toThrow(/[Tt]abs/);\n    });\n\n    test(\"throws YamlParseError for unclosed double quote\", () => {\n      expect(() => parseYaml('key: \"value')).toThrow(YamlParseError);\n      expect(() => parseYaml('key: \"value')).toThrow(/[Uu]nterminated/);\n    });\n\n    test(\"throws YamlParseError for unclosed single quote\", () => {\n      expect(() => parseYaml(\"key: 'value\")).toThrow(YamlParseError);\n      expect(() => parseYaml(\"key: 'value\")).toThrow(/[Uu]nterminated/);\n    });\n\n    test(\"throws YamlParseError for unclosed bracket\", () => {\n      expect(() => parseYaml(\"[1, 2\")).toThrow(YamlParseError);\n      expect(() => parseYaml(\"[1, 2\")).toThrow(/[Uu]nterminated/);\n    });\n\n    test(\"throws YamlParseError for unclosed brace\", () => {\n      expect(() => parseYaml(\"{a: 1\")).toThrow(YamlParseError);\n      expect(() => parseYaml(\"{a: 1\")).toThrow(/[Uu]nterminated/);\n    });\n\n    test(\"error includes line number\", () => {\n      try {\n        parseYaml('key: \"unclosed');\n      } catch (e) {\n        expect(e).toBeInstanceOf(YamlParseError);\n        expect((e as YamlParseError).line).toBe(1);\n      }\n    });\n\n    test(\"error includes column number\", () => {\n      try {\n        parseYaml('key: \"unclosed');\n      } catch (e) {\n        expect(e).toBeInstanceOf(YamlParseError);\n        expect((e as YamlParseError).column).toBeGreaterThan(0);\n      }\n    });\n  });\n\n  describe(\"complex structures\", () => {\n    test(\"parses array of objects\", () => {\n      const yaml = `- name: John\n  age: 30\n- name: Jane\n  age: 25`;\n      expect(parseYaml(yaml)).toEqual([\n        { name: \"John\", age: 30 },\n        { name: \"Jane\", age: 25 },\n      ]);\n    });\n\n    test(\"parses nested arrays\", () => {\n      const yaml = `matrix:\n  - [1, 2, 3]\n  - [4, 5, 6]`;\n      expect(parseYaml(yaml)).toEqual({\n        matrix: [\n          [1, 2, 3],\n          [4, 5, 6],\n        ],\n      });\n    });\n  });\n});\n"
