/**
 * Custom YAML parser for syntax validation.
 * Implements a subset of YAML 1.2 sufficient for typical configuration files.
 */

/**
 * Error thrown when YAML parsing fails.
 */
export class YamlParseError extends Error {
  constructor(
    message: string,
    public readonly line: number,
    public readonly column: number
  ) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = "YamlParseError";
  }
}

/**
 * Token types for the lexer.
 */
type TokenType =
  | "KEY"
  | "VALUE"
  | "INDENT"
  | "DEDENT"
  | "NEWLINE"
  | "DASH"
  | "COLON"
  | "LBRACKET"
  | "RBRACKET"
  | "LBRACE"
  | "RBRACE"
  | "COMMA"
  | "PIPE"
  | "GREATER"
  | "EOF";

/**
 * Token produced by the lexer.
 */
interface Token {
  type: TokenType;
  value: string;
  line: number;
  column: number;
}

/**
 * Lexer for tokenizing YAML content.
 */
class YamlLexer {
  private pos = 0;
  private line = 1;
  private column = 1;
  private indentStack: number[] = [0];
  private content: string;
  private tokens: Token[] = [];
  private atLineStart = true;

  constructor(content: string) {
    this.content = content;
  }

  tokenize(): Token[] {
    while (this.pos < this.content.length) {
      this.scanToken();
    }

    // Emit remaining DEDENTs at end of file
    while (this.indentStack.length > 1) {
      this.indentStack.pop();
      this.tokens.push({
        type: "DEDENT",
        value: "",
        line: this.line,
        column: this.column,
      });
    }

    this.tokens.push({
      type: "EOF",
      value: "",
      line: this.line,
      column: this.column,
    });

    return this.tokens;
  }

  private peek(offset = 0): string {
    return this.content[this.pos + offset] ?? "";
  }

  private advance(): string {
    const ch = this.content[this.pos];
    this.pos++;
    if (ch === "\n") {
      this.line++;
      this.column = 1;
      this.atLineStart = true;
    } else {
      this.column++;
    }
    return ch;
  }

  private scanToken(): void {
    // Handle line start indentation
    if (this.atLineStart) {
      this.handleIndentation();
      this.atLineStart = false;
      if (this.pos >= this.content.length) return;
    }

    const ch = this.peek();

    // Skip whitespace (not newlines)
    if (ch === " ") {
      this.advance();
      return;
    }

    // Check for tabs in indentation context
    if (ch === "\t") {
      throw new YamlParseError(
        "Tabs are not allowed for indentation in YAML",
        this.line,
        this.column
      );
    }

    // Newline
    if (ch === "\n") {
      this.tokens.push({
        type: "NEWLINE",
        value: "\n",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    // Carriage return (handle \r\n)
    if (ch === "\r") {
      this.advance();
      if (this.peek() === "\n") {
        this.tokens.push({
          type: "NEWLINE",
          value: "\n",
          line: this.line,
          column: this.column,
        });
        this.advance();
      }
      return;
    }

    // Comment
    if (ch === "#") {
      this.skipComment();
      return;
    }

    // Single character tokens
    if (ch === "-") {
      const nextCh = this.peek(1);
      if (nextCh === " " || nextCh === "\n" || nextCh === "" || nextCh === "\r") {
        this.tokens.push({
          type: "DASH",
          value: "-",
          line: this.line,
          column: this.column,
        });
        this.advance();
        return;
      }
      // Otherwise it could be a negative number or part of a value
    }

    if (ch === ":") {
      const nextCh = this.peek(1);
      if (nextCh === " " || nextCh === "\n" || nextCh === "" || nextCh === "\r") {
        this.tokens.push({
          type: "COLON",
          value: ":",
          line: this.line,
          column: this.column,
        });
        this.advance();
        return;
      }
    }

    if (ch === "[") {
      this.tokens.push({
        type: "LBRACKET",
        value: "[",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === "]") {
      this.tokens.push({
        type: "RBRACKET",
        value: "]",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === "{") {
      this.tokens.push({
        type: "LBRACE",
        value: "{",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === "}") {
      this.tokens.push({
        type: "RBRACE",
        value: "}",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === ",") {
      this.tokens.push({
        type: "COMMA",
        value: ",",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === "|") {
      this.tokens.push({
        type: "PIPE",
        value: "|",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    if (ch === ">") {
      this.tokens.push({
        type: "GREATER",
        value: ">",
        line: this.line,
        column: this.column,
      });
      this.advance();
      return;
    }

    // Quoted strings
    if (ch === '"' || ch === "'") {
      this.scanQuotedString(ch);
      return;
    }

    // Plain value (unquoted string, number, boolean, null, or key)
    this.scanPlainValue();
  }

  private handleIndentation(): void {
    let indent = 0;
    while (this.peek() === " ") {
      indent++;
      this.advance();
    }

    // Check for tabs
    if (this.peek() === "\t") {
      throw new YamlParseError(
        "Tabs are not allowed for indentation in YAML",
        this.line,
        this.column
      );
    }

    // Skip empty lines and comment-only lines
    if (this.peek() === "\n" || this.peek() === "\r" || this.peek() === "#" || this.peek() === "") {
      return;
    }

    const currentIndent = this.indentStack[this.indentStack.length - 1];

    if (indent > currentIndent) {
      this.indentStack.push(indent);
      this.tokens.push({
        type: "INDENT",
        value: "",
        line: this.line,
        column: 1,
      });
    } else if (indent < currentIndent) {
      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > indent) {
        this.indentStack.pop();
        this.tokens.push({
          type: "DEDENT",
          value: "",
          line: this.line,
          column: 1,
        });
      }
      if (this.indentStack[this.indentStack.length - 1] !== indent) {
        throw new YamlParseError(
          "Invalid indentation level",
          this.line,
          this.column
        );
      }
    }
  }

  private skipComment(): void {
    while (this.peek() !== "\n" && this.peek() !== "" && this.peek() !== "\r") {
      this.advance();
    }
  }

  private scanQuotedString(quote: string): void {
    const startLine = this.line;
    const startColumn = this.column;
    this.advance(); // consume opening quote

    let value = "";
    while (this.peek() !== quote) {
      if (this.peek() === "") {
        throw new YamlParseError(
          `Unterminated string literal`,
          startLine,
          startColumn
        );
      }
      if (this.peek() === "\n" || this.peek() === "\r") {
        throw new YamlParseError(
          `Unterminated string literal`,
          startLine,
          startColumn
        );
      }
      if (this.peek() === "\\" && quote === '"') {
        this.advance(); // consume backslash
        const escaped = this.peek();
        if (escaped === "") {
          throw new YamlParseError(
            `Unterminated string literal`,
            startLine,
            startColumn
          );
        }
        switch (escaped) {
          case "n":
            value += "\n";
            break;
          case "t":
            value += "\t";
            break;
          case "r":
            value += "\r";
            break;
          case "\\":
            value += "\\";
            break;
          case '"':
            value += '"';
            break;
          case "'":
            value += "'";
            break;
          default:
            value += escaped;
        }
        this.advance();
      } else {
        value += this.advance();
      }
    }
    this.advance(); // consume closing quote

    this.tokens.push({
      type: "VALUE",
      value,
      line: startLine,
      column: startColumn,
    });
  }

  private scanPlainValue(): void {
    const startLine = this.line;
    const startColumn = this.column;
    let value = "";

    // Check if this might be a key (followed by colon)
    const isKeyContext = this.lookAheadForColon();

    while (true) {
      const ch = this.peek();
      if (ch === "" || ch === "\n" || ch === "\r") break;
      if (ch === "#" && value.length > 0 && this.content[this.pos - 1] === " ") break;
      if (ch === ":" && (this.peek(1) === " " || this.peek(1) === "\n" || this.peek(1) === "" || this.peek(1) === "\r")) {
        if (isKeyContext) break;
      }
      if (ch === "," || ch === "]" || ch === "}" || ch === "[" || ch === "{") break;

      value += this.advance();
    }

    value = value.trim();

    if (value.length > 0) {
      this.tokens.push({
        type: "VALUE",
        value,
        line: startLine,
        column: startColumn,
      });
    }
  }

  private lookAheadForColon(): boolean {
    let i = this.pos;
    while (i < this.content.length) {
      const ch = this.content[i];
      if (ch === "\n" || ch === "\r") return false;
      if (ch === ":") {
        const next = this.content[i + 1] ?? "";
        return next === " " || next === "\n" || next === "" || next === "\r";
      }
      i++;
    }
    return false;
  }
}

/**
 * Parser for building JavaScript objects from tokens.
 */
class YamlParser {
  private tokens: Token[];
  private pos = 0;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  parse(): unknown {
    // Skip leading newlines
    this.skipNewlines();

    if (this.peek().type === "EOF") {
      return null;
    }

    const result = this.parseValue();
    this.skipNewlines();

    if (this.peek().type !== "EOF") {
      const token = this.peek();
      throw new YamlParseError(
        `Unexpected token '${token.value || token.type}'`,
        token.line,
        token.column
      );
    }

    return result;
  }

  private peek(offset = 0): Token {
    return this.tokens[this.pos + offset] ?? this.tokens[this.tokens.length - 1];
  }

  private advance(): Token {
    return this.tokens[this.pos++];
  }

  private skipNewlines(): void {
    while (this.peek().type === "NEWLINE") {
      this.advance();
    }
  }

  private parseValue(): unknown {
    this.skipNewlines();
    const token = this.peek();

    switch (token.type) {
      case "LBRACKET":
        return this.parseFlowSequence();
      case "LBRACE":
        return this.parseFlowMapping();
      case "DASH":
        return this.parseBlockSequence();
      case "PIPE":
      case "GREATER":
        return this.parseBlockScalar();
      case "VALUE":
        // Could be a scalar or start of a mapping
        if (this.isKeyValuePair()) {
          return this.parseBlockMapping();
        }
        return this.parseScalar();
      case "EOF":
        return null;
      default:
        throw new YamlParseError(
          `Unexpected token '${token.value || token.type}'`,
          token.line,
          token.column
        );
    }
  }

  private isKeyValuePair(): boolean {
    if (this.peek().type !== "VALUE") return false;
    const next = this.peek(1);
    return next.type === "COLON";
  }

  private parseScalar(): unknown {
    const token = this.advance();
    return this.convertScalar(token.value);
  }

  private convertScalar(value: string): unknown {
    // Null
    if (value === "null" || value === "~" || value === "") {
      return null;
    }

    // Booleans
    if (value === "true" || value === "yes") {
      return true;
    }
    if (value === "false" || value === "no") {
      return false;
    }

    // Numbers
    if (/^-?\d+$/.test(value)) {
      return parseInt(value, 10);
    }
    if (/^-?\d+\.\d+$/.test(value)) {
      return parseFloat(value);
    }

    // String
    return value;
  }

  private parseFlowSequence(): unknown[] {
    const startToken = this.advance(); // consume [
    const result: unknown[] = [];

    while (this.peek().type !== "RBRACKET") {
      if (this.peek().type === "EOF") {
        throw new YamlParseError(
          "Unterminated inline array",
          startToken.line,
          startToken.column
        );
      }

      // Skip whitespace-like tokens
      this.skipNewlines();

      if (this.peek().type === "RBRACKET") break;

      result.push(this.parseFlowValue());

      this.skipNewlines();

      if (this.peek().type === "COMMA") {
        this.advance();
      } else if (this.peek().type !== "RBRACKET") {
        const token = this.peek();
        if (token.type !== "EOF") {
          throw new YamlParseError(
            `Expected ',' or ']' in inline array`,
            token.line,
            token.column
          );
        }
      }
    }

    this.advance(); // consume ]
    return result;
  }

  private parseFlowMapping(): Record<string, unknown> {
    const startToken = this.advance(); // consume {
    const result: Record<string, unknown> = {};

    while (this.peek().type !== "RBRACE") {
      if (this.peek().type === "EOF") {
        throw new YamlParseError(
          "Unterminated inline object",
          startToken.line,
          startToken.column
        );
      }

      this.skipNewlines();

      if (this.peek().type === "RBRACE") break;

      // Parse key
      if (this.peek().type !== "VALUE") {
        const token = this.peek();
        throw new YamlParseError(
          `Expected key in inline object`,
          token.line,
          token.column
        );
      }
      const key = this.advance().value;

      // Expect colon
      if (this.peek().type !== "COLON") {
        const token = this.peek();
        throw new YamlParseError(
          `Expected ':' after key in inline object`,
          token.line,
          token.column
        );
      }
      this.advance(); // consume :

      // Parse value
      result[key] = this.parseFlowValue();

      this.skipNewlines();

      if (this.peek().type === "COMMA") {
        this.advance();
      } else if (this.peek().type !== "RBRACE") {
        const token = this.peek();
        if (token.type !== "EOF") {
          throw new YamlParseError(
            `Expected ',' or '}' in inline object`,
            token.line,
            token.column
          );
        }
      }
    }

    this.advance(); // consume }
    return result;
  }

  private parseFlowValue(): unknown {
    this.skipNewlines();
    const token = this.peek();

    switch (token.type) {
      case "LBRACKET":
        return this.parseFlowSequence();
      case "LBRACE":
        return this.parseFlowMapping();
      case "VALUE":
        return this.parseScalar();
      default:
        throw new YamlParseError(
          `Unexpected token '${token.value || token.type}' in flow context`,
          token.line,
          token.column
        );
    }
  }

  private parseBlockSequence(): unknown[] {
    const result: unknown[] = [];

    while (this.peek().type === "DASH") {
      this.advance(); // consume -

      // Check for nested content
      if (this.peek().type === "NEWLINE") {
        this.advance();
        if (this.peek().type === "INDENT") {
          this.advance();
          result.push(this.parseValue());
          this.skipNewlines();
          if (this.peek().type === "DEDENT") {
            this.advance();
          }
        } else {
          result.push(null);
        }
      } else if (this.peek().type === "INDENT") {
        this.advance();
        result.push(this.parseValue());
        this.skipNewlines();
        if (this.peek().type === "DEDENT") {
          this.advance();
        }
      } else {
        // Inline value after dash
        result.push(this.parseInlineValue());
      }

      this.skipNewlines();
    }

    return result;
  }

  private parseBlockMapping(): Record<string, unknown> {
    const result: Record<string, unknown> = {};

    while (this.peek().type === "VALUE" && this.isKeyValuePair()) {
      const key = this.advance().value;

      // Expect colon
      if (this.peek().type !== "COLON") {
        const token = this.peek();
        throw new YamlParseError(
          `Expected ':' after key`,
          token.line,
          token.column
        );
      }
      this.advance(); // consume :

      // Check what follows the colon
      if (this.peek().type === "NEWLINE") {
        this.advance();
        if (this.peek().type === "INDENT") {
          this.advance();
          result[key] = this.parseValue();
          this.skipNewlines();
          if (this.peek().type === "DEDENT") {
            this.advance();
          }
        } else {
          // Empty value
          result[key] = null;
        }
      } else if (this.peek().type === "INDENT") {
        this.advance();
        result[key] = this.parseValue();
        this.skipNewlines();
        if (this.peek().type === "DEDENT") {
          this.advance();
        }
      } else if (this.peek().type === "PIPE" || this.peek().type === "GREATER") {
        result[key] = this.parseBlockScalar();
      } else {
        // Inline value
        result[key] = this.parseInlineValue();
      }

      this.skipNewlines();
    }

    return result;
  }

  private parseInlineValue(): unknown {
    const token = this.peek();

    switch (token.type) {
      case "LBRACKET":
        return this.parseFlowSequence();
      case "LBRACE":
        return this.parseFlowMapping();
      case "VALUE":
        return this.parseScalar();
      case "NEWLINE":
      case "EOF":
      case "DEDENT":
        return null;
      default:
        throw new YamlParseError(
          `Unexpected token '${token.value || token.type}'`,
          token.line,
          token.column
        );
    }
  }

  private parseBlockScalar(): string {
    const scalarType = this.advance(); // consume | or >
    const isLiteral = scalarType.type === "PIPE";

    // Skip to next line
    if (this.peek().type === "NEWLINE") {
      this.advance();
    }

    // Expect indent
    if (this.peek().type !== "INDENT") {
      return "";
    }
    this.advance();

    const lines: string[] = [];

    // Collect lines until dedent
    while (this.peek().type !== "DEDENT" && this.peek().type !== "EOF") {
      if (this.peek().type === "VALUE") {
        lines.push(this.advance().value);
      } else if (this.peek().type === "NEWLINE") {
        if (lines.length > 0) {
          lines.push("");
        }
        this.advance();
      } else {
        break;
      }
    }

    if (this.peek().type === "DEDENT") {
      this.advance();
    }

    if (isLiteral) {
      return lines.join("\n");
    } else {
      // Folded: join with spaces, but preserve double newlines
      return lines.join(" ").replace(/  +/g, "\n");
    }
  }
}

/**
 * Parse YAML content and return the corresponding JavaScript value.
 * @param content - The YAML string to parse
 * @returns The parsed JavaScript value
 * @throws YamlParseError if the YAML is invalid
 */
export function parseYaml(content: string): unknown {
  const lexer = new YamlLexer(content);
  const tokens = lexer.tokenize();
  const parser = new YamlParser(tokens);
  return parser.parse();
}

