test('empty document returns null', () => {
  assertEqual(parseYaml(''), null);
});

// Simple key-value
test('simple key-value', () => {
  assertEqual(parseYaml('key: value'), {key: 'value'});
});

// Nested object
test('nested object', () => {
  assertEqual(parseYaml('a:\\n  b: c'), {a: {b: 'c'}});
});

// Block array
test('block array', () => {
  assertEqual(parseYaml('- a\\n- b'), ['a', 'b']);
});

// Inline array
test('inline array', () => {
  assertEqual(parseYaml('[1, 2, 3]'), [1, 2, 3]);
});

// Inline object
test('inline object', () => {
  assertEqual(parseYaml('{a: 1, b: 2}'), {a: 1, b: 2});
});

// Numbers
test('integer', () => {
  assertEqual(parseYaml('count: 42'), {count: 42});
});

test('float', () => {
  assertEqual(parseYaml('pi: 3.14'), {pi: 3.14});
});

test('negative number', () => {
  assertEqual(parseYaml('temp: -7'), {temp: -7});
});

// Booleans
