  assertEqual(parseYaml('flag: yes'), {flag: true});
});

test('boolean no', () => {
  assertEqual(parseYaml('flag: no'), {flag: false});
});

// Null
test('null explicit', () => {
  assertEqual(parseYaml('value: null'), {value: null});
});

test('null tilde', () => {
  assertEqual(parseYaml('value: ~'), {value: null});
});

// Quoted strings
test('double quoted string', () => {
  assertEqual(parseYaml('name: \"hello\"'), {name: 'hello'});
});

test('single quoted string', () => {
  assertEqual(parseYaml(\"name: 'world'\"), {name: 'world'});
});

// Comments
