private parseBlockScalar(): string {
  const scalarType = this.advance(); // consume | or >
  const isLiteral = scalarType.type === "PIPE";

  // Skip to next line
  if (this.peek().type === "NEWLINE") {
    this.advance();
  }

  // Expect indent
  if (this.peek().type !== "INDENT") {
    return "";
  }
  this.advance();

  const lines: string[] = [];

  // Collect lines until dedent
  while (this.peek().type !== "DEDENT" && this.peek().type !== "EOF") {
    if (this.peek().type === "VALUE") {
      lines.push(this.advance().value);
    } else if (this.peek().type === "NEWLINE") {
      this.advance();
      // Only add empty line if we see content continues (not at dedent/EOF)
      if (this.peek().type === "VALUE") {
        // Content continues, no blank line to add
      } else if (this.peek().type !== "DEDENT" && this.peek().type !== "EOF") {
        lines.push("");
      }
    } else {
      break;
    }
  }

  if (this.peek().type === "DEDENT") {
    this.advance();
  }

  if (isLiteral) {
    return lines.join("\n");
  } else {
    // Folded: join adjacent lines with space
    return lines.filter(l => l !== "").join(" ");
  }
}

