private parseBlockMapping(): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  let continuationIndentCount = 0;

  while (true) {
    // Handle continuation indent (for multi-line mappings after dash)
    if (this.peek().type === "INDENT" && this.peek(1).type === "VALUE" && this.isKeyValuePairAt(1)) {
      this.advance();
      continuationIndentCount++;
    }

    // Check for key-value pair
    if (!(this.peek().type === "VALUE" && this.isKeyValuePair())) {
      break;
    }

    const key = this.advance().value;

    // Expect colon
    if (this.peek().type !== "COLON") {
      const token = this.peek();
      throw new YamlParseError(
        `Expected ':' after key`,
        token.line,
        token.column
      );
    }
    this.advance(); // consume :

    // Check what follows the colon
    if (this.peek().type === "NEWLINE") {
      this.advance();
      if (this.peek().type === "INDENT") {
        this.advance();
        result[key] = this.parseValue();
        this.skipNewlines();
        if (this.peek().type === "DEDENT") {
          this.advance();
        }
      } else {
        // Empty value
        result[key] = null;
      }
    } else if (this.peek().type === "INDENT") {
      this.advance();
      result[key] = this.parseValue();
      this.skipNewlines();
      if (this.peek().type === "DEDENT") {
        this.advance();
      }
    } else if (this.peek().type === "PIPE" || this.peek().type === "GREATER") {
      result[key] = this.parseBlockScalar();
    } else {
      // Inline value
      result[key] = this.parseInlineValue();
    }

    this.skipNewlines();
  }

  // Consume any DEDENT tokens matching continuation indents we consumed
  while (continuationIndentCount > 0 && this.peek().type === "DEDENT") {
    this.advance();
    continuationIndentCount--;
  }

  return result;
}

private isKeyValuePairAt(offset: number): boolean {
  if (this.peek(offset).type !== "VALUE") return false;
  const next = this.peek(offset + 1);
  return next.type === "COLON";
}

