import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { join } from "path";
import { mkdtemp, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";

describe("validate CLI", () => {
  let tempDir: string;

  beforeAll(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "yaml-test-"));
  });

  afterAll(async () => {
    await rm(tempDir, { recursive: true });
  });

  async function runValidate(
    args: string[]
  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
    const proc = Bun.spawn(["bun", "run", "src/validate.ts", ...args], {
      cwd: import.meta.dir.replace("/src", ""),
      stdout: "pipe",
      stderr: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    return { stdout, stderr, exitCode };
  }

  describe("valid YAML file", () => {
    test("returns exit 0 with success message", async () => {
      const filePath = join(tempDir, "valid.yaml");
      await writeFile(filePath, "key: value\ncount: 42");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Valid YAML:");
      expect(result.stdout).toContain(filePath);
    });

    test("validates empty YAML file as valid", async () => {
      const filePath = join(tempDir, "empty.yaml");
      await writeFile(filePath, "");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Valid YAML:");
    });
  });

  describe("invalid YAML file", () => {
    test("returns exit 1 with error message for syntax error", async () => {
      const filePath = join(tempDir, "invalid.yaml");
      await writeFile(filePath, 'key: "unclosed');

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Invalid YAML:");
      expect(result.stdout).toContain(filePath);
      expect(result.stdout).toContain("Error:");
    });

    test("returns exit 1 for tab indentation", async () => {
      const filePath = join(tempDir, "tabs.yaml");
      await writeFile(filePath, "key:\n\tvalue: nested");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Invalid YAML:");
    });
  });

  describe("file not found", () => {
    test("returns exit 1 with file not found message", async () => {
      const filePath = join(tempDir, "nonexistent.yaml");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stderr).toContain("File not found:");
      expect(result.stderr).toContain(filePath);
    });
  });

  describe("no arguments", () => {
    test("returns exit 1 with usage message", async () => {
      const result = await runValidate([]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Usage:");
      expect(result.stdout).toContain("bun run validate");
      expect(result.stdout).toContain("<file.yaml>");
    });
  });

  describe("file path handling", () => {
    test("handles absolute path", async () => {
      const filePath = join(tempDir, "absolute.yaml");
      await writeFile(filePath, "name: test");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
    });

    test("handles relative path", async () => {
      const filePath = join(tempDir, "relative.yaml");
      await writeFile(filePath, "data: 123");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
    });
  });
});

