/**
 * CLI entry point for YAML validation.
 * Validates YAML file syntax and reports results with appropriate exit codes.
 */

import { parseYaml, YamlParseError } from "./yaml-parser";

function printUsage(): void {
  console.log("Usage: bun run validate <file.yaml>");
  console.log("Validates YAML file syntax.");
}

async function readFile(filePath: string): Promise<string> {
  const file = Bun.file(filePath);
  const exists = await file.exists();

  if (!exists) {
    throw new Error(`File not found: ${filePath}`);
  }

  try {
    return await file.text();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Cannot read file: ${filePath}\n${message}`);
  }
}

function handleError(error: unknown, filePath: string): void {
  if (error instanceof Error) {
    if (error.message.startsWith("File not found:")) {
      console.error(`Error: ${error.message}`);
    } else if (error.message.startsWith("Cannot read file:")) {
      console.error(`Error: ${error.message}`);
    } else if (error instanceof YamlParseError) {
      console.log(`Invalid YAML: ${filePath}`);
      console.log(`Error: ${error.message}`);
    } else {
      console.log(`Invalid YAML: ${filePath}`);
      console.log(`Error: ${error.message}`);
    }
  } else {
    console.log(`Invalid YAML: ${filePath}`);
    console.log(`Error: ${String(error)}`);
  }
}

async function main(): Promise<void> {
  const filePath = process.argv[2];

  if (!filePath) {
    printUsage();
    process.exit(1);
  }

  try {
    const content = await readFile(filePath);
    parseYaml(content);
    console.log(`Valid YAML: ${filePath}`);
    process.exit(0);
  } catch (error) {
    handleError(error, filePath);
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";
import { parseYaml, YamlParseError } from "./yaml-parser";

describe("yaml-parser", () => {
  describe("empty document", () => {
    test("returns null for empty string", () => {
      expect(parseYaml("")).toBe(null);
    });

    test("returns null for whitespace only", () => {
      expect(parseYaml("   \n  \n")).toBe(null);
    });
  });

  describe("simple key-value pairs", () => {
    test("parses simple key-value", () => {
      expect(parseYaml("key: value")).toEqual({ key: "value" });
    });

    test("parses multiple key-value pairs", () => {
      expect(parseYaml("name: John\nage: 30")).toEqual({
        name: "John",
        age: 30,
      });
    });
  });

  describe("nested objects", () => {
    test("parses nested object via indentation", () => {
      const yaml = `a:
  b: c`;
      expect(parseYaml(yaml)).toEqual({ a: { b: "c" } });
    });

    test("parses deeply nested objects", () => {
      const yaml = `level1:
  level2:
    level3: value`;
      expect(parseYaml(yaml)).toEqual({
        level1: { level2: { level3: "value" } },
      });
    });
  });

  describe("block arrays", () => {
    test("parses block array with dash syntax", () => {
      const yaml = `- a
- b`;
      expect(parseYaml(yaml)).toEqual(["a", "b"]);
    });

    test("parses array with numeric values", () => {
      const yaml = `- 1
- 2
- 3`;
      expect(parseYaml(yaml)).toEqual([1, 2, 3]);
    });

    test("parses array nested in object", () => {
      const yaml = `items:
  - first
  - second`;
      expect(parseYaml(yaml)).toEqual({ items: ["first", "second"] });
    });
  });

  describe("inline arrays", () => {
    test("parses inline array with numbers", () => {
      expect(parseYaml("[1, 2, 3]")).toEqual([1, 2, 3]);
    });

    test("parses inline array with strings", () => {
      expect(parseYaml("[a, b, c]")).toEqual(["a", "b", "c"]);
    });

    test("parses inline array in object", () => {
      expect(parseYaml("items: [1, 2, 3]")).toEqual({ items: [1, 2, 3] });
    });

    test("parses empty inline array", () => {
      expect(parseYaml("[]")).toEqual([]);
    });
  });

  describe("inline objects", () => {
    test("parses inline object", () => {
      expect(parseYaml("{a: 1, b: 2}")).toEqual({ a: 1, b: 2 });
    });

    test("parses inline object in object", () => {
      expect(parseYaml("data: {x: 10, y: 20}")).toEqual({
        data: { x: 10, y: 20 },
      });
    });

    test("parses empty inline object", () => {
      expect(parseYaml("{}")).toEqual({});
    });
  });

  describe("numbers", () => {
    test("parses integer", () => {
      expect(parseYaml("count: 42")).toEqual({ count: 42 });
    });

    test("parses negative integer", () => {
      expect(parseYaml("value: -7")).toEqual({ value: -7 });
    });

    test("parses float", () => {
      expect(parseYaml("pi: 3.14")).toEqual({ pi: 3.14 });
    });

    test("parses negative float", () => {
      expect(parseYaml("temp: -2.5")).toEqual({ temp: -2.5 });
    });
  });

  describe("booleans", () => {
    test("parses true", () => {
      expect(parseYaml("flag: true")).toEqual({ flag: true });
    });

    test("parses false", () => {
      expect(parseYaml("flag: false")).toEqual({ flag: false });
    });

    test("parses yes as true", () => {
      expect(parseYaml("enabled: yes")).toEqual({ enabled: true });
    });

    test("parses no as false", () => {
      expect(parseYaml("enabled: no")).toEqual({ enabled: false });
    });
  });

  describe("null", () => {
    test("parses null keyword", () => {
      expect(parseYaml("value: null")).toEqual({ value: null });
    });

    test("parses tilde as null", () => {
      expect(parseYaml("value: ~")).toEqual({ value: null });
    });

    test("parses empty value as null", () => {
      expect(parseYaml("value:")).toEqual({ value: null });
    });
  });

  describe("quoted strings", () => {
    test("parses double-quoted string", () => {
      expect(parseYaml('name: "hello"')).toEqual({ name: "hello" });
    });

    test("parses single-quoted string", () => {
      expect(parseYaml("name: 'world'")).toEqual({ name: "world" });
    });

    test("parses string with escape sequences", () => {
      expect(parseYaml('text: "hello\\nworld"')).toEqual({
        text: "hello\nworld",
      });
    });

    test("parses string that looks like number when quoted", () => {
      expect(parseYaml('code: "42"')).toEqual({ code: "42" });
    });
  });

  describe("multiline strings", () => {
    test("parses literal block scalar with pipe", () => {
      const yaml = `text: |
  line1
  line2`;
      expect(parseYaml(yaml)).toEqual({ text: "line1\nline2" });
    });

    test("parses folded block scalar with greater", () => {
      const yaml = `text: >
  line1
  line2`;
      expect(parseYaml(yaml)).toEqual({ text: "line1 line2" });
    });
  });

  describe("comments", () => {
    test("ignores comment at start", () => {
      const yaml = `# comment
key: value`;
      expect(parseYaml(yaml)).toEqual({ key: "value" });
    });

    test("ignores inline comment", () => {
      expect(parseYaml("key: value # this is a comment")).toEqual({
        key: "value",
      });
    });

    test("ignores comment-only lines", () => {
      const yaml = `a: 1
# middle comment
b: 2`;
      expect(parseYaml(yaml)).toEqual({ a: 1, b: 2 });
    });
  });

  describe("error cases", () => {
    test("throws YamlParseError for invalid indentation", () => {
      const yaml = `a:
   b: c
  d: e`;
      expect(() => parseYaml(yaml)).toThrow(YamlParseError);
    });

    test("throws YamlParseError for tabs in indentation", () => {
      const yaml = "a:\n\tb: c";
      expect(() => parseYaml(yaml)).toThrow(YamlParseError);
      expect(() => parseYaml(yaml)).toThrow(/[Tt]abs/);
    });

    test("throws YamlParseError for unclosed double quote", () => {
      expect(() => parseYaml('key: "value')).toThrow(YamlParseError);
      expect(() => parseYaml('key: "value')).toThrow(/[Uu]nterminated/);
    });

    test("throws YamlParseError for unclosed single quote", () => {
      expect(() => parseYaml("key: 'value")).toThrow(YamlParseError);
      expect(() => parseYaml("key: 'value")).toThrow(/[Uu]nterminated/);
    });

    test("throws YamlParseError for unclosed bracket", () => {
      expect(() => parseYaml("[1, 2")).toThrow(YamlParseError);
      expect(() => parseYaml("[1, 2")).toThrow(/[Uu]nterminated/);
    });

    test("throws YamlParseError for unclosed brace", () => {
      expect(() => parseYaml("{a: 1")).toThrow(YamlParseError);
      expect(() => parseYaml("{a: 1")).toThrow(/[Uu]nterminated/);
    });

    test("error includes line number", () => {
      try {
        parseYaml('key: "unclosed');
      } catch (e) {
        expect(e).toBeInstanceOf(YamlParseError);
        expect((e as YamlParseError).line).toBe(1);
      }
    });

    test("error includes column number", () => {
      try {
        parseYaml('key: "unclosed');
      } catch (e) {
        expect(e).toBeInstanceOf(YamlParseError);
        expect((e as YamlParseError).column).toBeGreaterThan(0);
      }
    });
  });

  describe("complex structures", () => {
    test("parses array of objects", () => {
      const yaml = `- name: John
  age: 30
- name: Jane
  age: 25`;
      expect(parseYaml(yaml)).toEqual([
        { name: "John", age: 30 },
        { name: "Jane", age: 25 },
      ]);
    });

    test("parses nested arrays", () => {
      const yaml = `matrix:
  - [1, 2, 3]
  - [4, 5, 6]`;
      expect(parseYaml(yaml)).toEqual({
        matrix: [
          [1, 2, 3],
          [4, 5, 6],
        ],
      });
    });
  });
});

import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { join } from "path";
import { mkdtemp, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";

describe("validate CLI", () => {
  let tempDir: string;

  beforeAll(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "yaml-test-"));
  });

  afterAll(async () => {
    await rm(tempDir, { recursive: true });
  });

  async function runValidate(
    args: string[]
  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
    const proc = Bun.spawn(["bun", "run", "src/validate.ts", ...args], {
      cwd: import.meta.dir.replace("/src", ""),
      stdout: "pipe",
      stderr: "pipe",
    });

    const stdout = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    return { stdout, stderr, exitCode };
  }

  describe("valid YAML file", () => {
    test("returns exit 0 with success message", async () => {
      const filePath = join(tempDir, "valid.yaml");
      await writeFile(filePath, "key: value\ncount: 42");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Valid YAML:");
      expect(result.stdout).toContain(filePath);
    });

    test("validates empty YAML file as valid", async () => {
      const filePath = join(tempDir, "empty.yaml");
      await writeFile(filePath, "");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Valid YAML:");
    });
  });

  describe("invalid YAML file", () => {
    test("returns exit 1 with error message for syntax error", async () => {
      const filePath = join(tempDir, "invalid.yaml");
      await writeFile(filePath, 'key: "unclosed');

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Invalid YAML:");
      expect(result.stdout).toContain(filePath);
      expect(result.stdout).toContain("Error:");
    });

    test("returns exit 1 for tab indentation", async () => {
      const filePath = join(tempDir, "tabs.yaml");
      await writeFile(filePath, "key:\n\tvalue: nested");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Invalid YAML:");
    });
  });

  describe("file not found", () => {
    test("returns exit 1 with file not found message", async () => {
      const filePath = join(tempDir, "nonexistent.yaml");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stderr).toContain("File not found:");
      expect(result.stderr).toContain(filePath);
    });
  });

  describe("no arguments", () => {
    test("returns exit 1 with usage message", async () => {
      const result = await runValidate([]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Usage:");
      expect(result.stdout).toContain("bun run validate");
      expect(result.stdout).toContain("<file.yaml>");
    });
  });

  describe("file path handling", () => {
    test("handles absolute path", async () => {
      const filePath = join(tempDir, "absolute.yaml");
      await writeFile(filePath, "name: test");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
    });

    test("handles relative path", async () => {
      const filePath = join(tempDir, "relative.yaml");
      await writeFile(filePath, "data: 123");

      const result = await runValidate([filePath]);

      expect(result.exitCode).toBe(0);
    });
  });
});

