        "file_path": "/tmp/hypothesis-yaml-validator/yaml-parser.ts",
        "content": "/**\n * Pure TypeScript YAML Syntax Validator Prototype\n * Tests HYP-001: Can we validate YAML 1.1/1.2 syntax without dependencies?\n *\n * DISPOSABLE CODE - For hypothesis validation only\n */\n\ntype YAMLValue = string | number | boolean | null | YAMLValue[] | { [key: string]: YAMLValue };\n\ninterface ParseResult {\n  valid: boolean;\n  error?: string;\n  line?: number;\n  documents?: YAMLValue[];\n}\n\ninterface Token {\n  type: 'key' | 'value' | 'indent' | 'list-item' | 'comment' | 'doc-start' | 'doc-end' | 'multiline-literal' | 'multiline-folded' | 'newline';\n  value: string;\n  line: number;\n  indent: number;\n}\n\nclass YAMLValidator {\n  private lines: string[] = [];\n  private currentLine = 0;\n\n  parse(input: string): ParseResult {\n    this.lines = input.split('\\n');\n    this.currentLine = 0;\n\n    try {\n      const documents: YAMLValue[] = [];\n\n      while (this.currentLine < this.lines.length) {\n        const line = this.lines[this.currentLine];\n\n        // Skip empty lines and comments at document level\n        if (this.isEmptyOrComment(line)) {\n          this.currentLine++;\n          continue;\n        }\n\n        // Check for document start marker\n        if (line.trim() === '---') {\n          this.currentLine++;\n          continue;\n        }\n\n        // Check for document end marker\n        if (line.trim() === '...') {\n          this.currentLine++;\n          continue;\n        }\n\n        // Parse a document\n        const doc = this.parseValue(0);\n        if (doc !== undefined) {\n          documents.push(doc);\n        }\n      }\n\n      return { valid: true, documents };\n    } catch (e) {\n      const error = e as Error;\n      return {\n        valid: false,\n        error: error.message,\n        line: this.currentLine + 1\n      };\n    }\n  }\n\n  private isEmptyOrComment(line: string): boolean {\n    const trimmed = line.trim();\n    return trimmed === '' || trimmed.startsWith('#');\n  }\n\n  private getIndent(line: string): number {\n    const match = line.match(/^(\\s*)/);\n    return match ? match[1].length : 0;\n  }\n\n  private parseValue(expectedIndent: number): YAMLValue {\n    while (this.currentLine < this.lines.length) {\n      const line = this.lines[this.currentLine];\n\n      if (this.isEmptyOrComment(line)) {\n        this.currentLine++;\n        continue;\n      }\n\n      const indent = this.getIndent(line);\n      const trimmed = line.trim();\n\n      // Document markers at value level\n      if (trimmed === '---' || trimmed === '...') {\n        return null as unknown as YAMLValue;\n      }\n\n      // Check if we've dedented past expected level\n      if (indent < expectedIndent) {\n        return null as unknown as YAMLValue;\n      }\n\n      // List item\n      if (trimmed.startsWith('- ') || trimmed === '-') {\n        return this.parseList(indent);\n      }\n\n      // Key-value pair\n      if (trimmed.includes(':')) {\n        return this.parseMapping(indent);\n      }\n\n      // Scalar value\n      return this.parseScalar(trimmed);\n    }\n\n    return null as unknown as YAMLValue;\n  }\n\n  private parseMapping(baseIndent: number): { [key: string]: YAMLValue } {\n    const result: { [key: string]: YAMLValue } = {};\n\n    while (this.currentLine < this.lines.length) {\n      const line = this.lines[this.currentLine];\n\n      if (this.isEmptyOrComment(line)) {\n        this.currentLine++;\n        continue;\n      }\n\n      const indent = this.getIndent(line);\n      const trimmed = line.trim();\n\n      // Document markers\n      if (trimmed === '---' || trimmed === '...') {\n        break;\n      }\n\n      // Dedented - end of this mapping\n      if (indent < baseIndent) {\n        break;\n      }\n\n      // Different indent level than base - error unless nested\n      if (indent > baseIndent && Object.keys(result).length === 0) {\n        throw new Error(`Unexpected indent at line ${this.currentLine + 1}`);\n      }\n\n      if (indent > baseIndent) {\n        break;\n      }\n\n      // List item at same level - end mapping\n      if (trimmed.startsWith('- ')) {\n        break;\n      }\n\n      // Parse key-value\n      const colonIndex = this.findColonIndex(trimmed);\n      if (colonIndex === -1) {\n        throw new Error(`Missing colon in key-value pair at line ${this.currentLine + 1}`);\n      }\n\n      const key = trimmed.substring(0, colonIndex).trim();\n      const afterColon = trimmed.substring(colonIndex + 1).trim();\n\n      // Validate key\n      if (!this.isValidKey(key)) {\n        throw new Error(`Invalid key \"${key}\" at line ${this.currentLine + 1}`);\n      }\n\n      this.currentLine++;\n\n      // Check for multi-line string indicators\n      if (afterColon === '|' || afterColon === '|+' || afterColon === '|-') {\n        result[key] = this.parseLiteralBlock(baseIndent);\n      } else if (afterColon === '>' || afterColon === '>+' || afterColon === '>-') {\n        result[key] = this.parseFoldedBlock(baseIndent);\n      } else if (afterColon === '') {\n        // Value on next line(s)\n        const nextLine = this.peekNextNonEmpty();\n        if (nextLine && this.getIndent(nextLine) > indent) {\n          result[key] = this.parseValue(this.getIndent(nextLine));\n        } else {\n          result[key] = null;\n        }\n      } else {\n        // Inline value\n        result[key] = this.parseScalar(afterColon);\n      }\n    }\n\n    return result;\n  }\n\n  private findColonIndex(line: string): number {\n    let inSingleQuote = false;\n    let inDoubleQuote = false;\n\n    for (let i = 0; i < line.length; i++) {\n      const char = line[i];\n      const prevChar = i > 0 ? line[i - 1] : '';\n\n      if (char === \"'\" && !inDoubleQuote && prevChar !== '\\\\') {\n        inSingleQuote = !inSingleQuote;\n      } else if (char === '\"' && !inSingleQuote && prevChar !== '\\\\') {\n        inDoubleQuote = !inDoubleQuote;\n      } else if (char === ':' && !inSingleQuote && !inDoubleQuote) {\n        // Colon must be followed by space, newline, or end of string\n        if (i === line.length - 1 || line[i + 1] === ' ' || line[i + 1] === '\\t') {\n          return i;\n        }\n      }\n    }\n\n    // Check for unclosed quotes\n    if (inSingleQuote) {\n      throw new Error(`Unclosed single quote at line ${this.currentLine + 1}`);\n    }\n    if (inDoubleQuote) {\n      throw new Error(`Unclosed double quote at line ${this.currentLine + 1}`);\n    }\n\n    return -1;\n  }\n\n  private isValidKey(key: string): boolean {\n    if (key === '') return false;\n\n    // Check for unclosed quotes in key\n    if ((key.startsWith('\"') && !key.endsWith('\"')) ||\n        (key.startsWith(\"'\") && !key.endsWith(\"'\"))) {\n      throw new Error(`Unclosed quote in key at line ${this.currentLine + 1}`);\n    }\n\n    return true;\n  }\n\n  private parseList(baseIndent: number): YAMLValue[] {\n    const result: YAMLValue[] = [];\n\n    while (this.currentLine < this.lines.length) {\n      const line = this.lines[this.currentLine];\n\n      if (this.isEmptyOrComment(line)) {\n        this.currentLine++;\n        continue;\n      }\n\n      const indent = this.getIndent(line);\n      const trimmed = line.trim();\n\n      // Document markers\n      if (trimmed === '---' || trimmed === '...') {\n        break;\n      }\n\n      // Dedented - end of list\n      if (indent < baseIndent) {\n        break;\n      }\n\n      // Not a list item at this level\n      if (!trimmed.startsWith('- ') && trimmed !== '-') {\n        if (indent === baseIndent) {\n          break;\n        }\n      }\n\n      if (trimmed.startsWith('- ') || trimmed === '-') {\n        const afterDash = trimmed.substring(1).trim();\n        this.currentLine++;\n\n        if (afterDash === '') {\n          // Complex list item or null\n          const nextLine = this.peekNextNonEmpty();\n          if (nextLine && this.getIndent(nextLine) > indent) {\n            result.push(this.parseValue(this.getIndent(nextLine)));\n          } else {\n            result.push(null);\n          }\n        } else if (afterDash.includes(':')) {\n          // Inline mapping in list\n          this.currentLine--; // Back up to reparse\n          const mappingLine = this.lines[this.currentLine];\n          const dashRemoved = mappingLine.replace(/^(\\s*)- /, '$1  ');\n          this.lines[this.currentLine] = dashRemoved;\n          result.push(this.parseMapping(indent + 2));\n          this.lines[this.currentLine - 1] = mappingLine; // Restore (already moved past)\n        } else {\n          result.push(this.parseScalar(afterDash));\n        }\n      } else {\n        break;\n      }\n    }\n\n    return result;\n  }\n\n  private parseLiteralBlock(baseIndent: number): string {\n    const lines: string[] = [];\n    let blockIndent: number | null = null;\n\n    while (this.currentLine < this.lines.length) {\n      const line = this.lines[this.currentLine];\n      const indent = this.getIndent(line);\n\n      // Empty line within block\n      if (line.trim() === '') {\n        if (blockIndent !== null) {\n          lines.push('');\n        }\n        this.currentLine++;\n        continue;\n      }\n\n      // First content line establishes indent\n      if (blockIndent === null) {\n        if (indent <= baseIndent) {\n          break;\n        }\n        blockIndent = indent;\n      }\n\n      // Dedented - end of block\n      if (indent < blockIndent) {\n        break;\n      }\n\n      lines.push(line.substring(blockIndent));\n      this.currentLine++;\n    }\n\n    return lines.join('\\n');\n  }\n\n  private parseFoldedBlock(baseIndent: number): string {\n    const lines: string[] = [];\n    let blockIndent: number | null = null;\n\n    while (this.currentLine < this.lines.length) {\n      const line = this.lines[this.currentLine];\n      const indent = this.getIndent(line);\n\n      if (line.trim() === '') {\n        if (blockIndent !== null) {\n          lines.push('');\n        }\n        this.currentLine++;\n        continue;\n      }\n\n      if (blockIndent === null) {\n        if (indent <= baseIndent) {\n          break;\n        }\n        blockIndent = indent;\n      }\n\n      if (indent < blockIndent) {\n        break;\n      }\n\n      lines.push(line.substring(blockIndent));\n      this.currentLine++;\n    }\n\n    // Fold: join non-empty consecutive lines with space\n    return lines.join(' ').replace(/\\s+/g, ' ').trim();\n  }\n\n  private parseScalar(value: string): YAMLValue {\n    // Remove inline comments\n    const commentIndex = this.findCommentIndex(value);\n    if (commentIndex !== -1) {\n      value = value.substring(0, commentIndex).trim();\n    }\n\n    // Null\n    if (value === '' || value === 'null' || value === 'Null' || value === 'NULL' || value === '~') {\n      return null;\n    }\n\n    // Boolean\n    if (value === 'true' || value === 'True' || value === 'TRUE' ||\n        value === 'yes' || value === 'Yes' || value === 'YES' ||\n        value === 'on' || value === 'On' || value === 'ON') {\n      return true;\n    }\n    if (value === 'false' || value === 'False' || value === 'FALSE' ||\n        value === 'no' || value === 'No' || value === 'NO' ||\n        value === 'off' || value === 'Off' || value === 'OFF') {\n      return false;\n    }\n\n    // Quoted string\n    if ((value.startsWith('\"') && value.endsWith('\"')) ||\n        (value.startsWith(\"'\") && value.endsWith(\"'\"))) {\n      return value.slice(1, -1);\n    }\n\n    // Check for unclosed quotes\n    if (value.startsWith('\"') || value.startsWith(\"'\")) {\n      throw new Error(`Unclosed quote at line ${this.currentLine + 1}`);\n    }\n\n    // Number (integer)\n    if (/^-?\\d+$/.test(value)) {\n      return parseInt(value, 10);\n    }\n\n    // Number (float)\n    if (/^-?\\d+\\.\\d+$/.test(value) || /^-?\\d+[eE][+-]?\\d+$/.test(value)) {\n      return parseFloat(value);\n    }\n\n    // Special floats\n    if (value === '.inf' || value === '.Inf' || value === '.INF') {\n      return Infinity;\n    }\n    if (value === '-.inf' || value === '-.Inf' || value === '-.INF') {\n      return -Infinity;\n    }\n    if (value === '.nan' || value === '.NaN' || value === '.NAN') {\n      return NaN;\n    }\n\n    // Plain string\n    return value;\n  }\n\n  private findCommentIndex(value: string): number {\n    let inSingleQuote = false;\n    let inDoubleQuote = false;\n\n    for (let i = 0; i < value.length; i++) {\n      const char = value[i];\n      const prevChar = i > 0 ? value[i - 1] : '';\n\n      if (char === \"'\" && !inDoubleQuote && prevChar !== '\\\\') {\n        inSingleQuote = !inSingleQuote;\n      } else if (char === '\"' && !inSingleQuote && prevChar !== '\\\\') {\n        inDoubleQuote = !inDoubleQuote;\n      } else if (char === '#' && !inSingleQuote && !inDoubleQuote && prevChar === ' ') {\n        return i - 1;\n      }\n    }\n\n    return -1;\n  }\n\n  private peekNextNonEmpty(): string | null {\n    for (let i = this.currentLine; i < this.lines.length; i++) {\n      const line = this.lines[i];\n      if (!this.isEmptyOrComment(line)) {\n        return line;\n      }\n    }\n    return null;\n  }\n}\n\n// ============ TEST SUITE ============\n\nconst validator = new YAMLValidator();\n\nconsole.log('=== HYP-001 Validation Tests ===\\n');\n\n// Test 1: Simple key-value pairs\nconsole.log('Test 1: Simple key-value pairs');\nconst test1 = `\nname: John Doe\nage: 30\nactive: true\n`;\nlet result = validator.parse(test1);\nconsole.log('  Valid:', result.valid);\nconsole.log('  Parsed:', JSON.stringify(result.documents, null, 2));\n\n// Test 2: Nested objects\nconsole.log('\\nTest 2: Nested objects');\nconst test2 = `\ndatabase:\n  host: localhost\n  port: 5432\n  credentials:\n    username: admin\n    password: secret\n`;\nresult = validator.parse(test2);\nconsole.log('  Valid:', result.valid);\nconsole.log('  Parsed:', JSON.stringify(result.documents, null, 2));\n