      "input": {
        "file_path": "/private/tmp/rp1-evals/17773350/workspace/.rp1/work/worktrees/feature-yaml-validator/src/commands/yaml-validate/yaml-parser.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport { parseYaml } from \"./yaml-parser\";\n\ndescribe(\"parseYaml\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"handles empty file\", () => {\n      const result = parseYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"handles whitespace-only file\", () => {\n      const result = parseYaml(\"   \\n\\n   \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"handles comments-only file\", () => {\n      const result = parseYaml(\"# This is a comment\\n# Another comment\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates simple key-value pairs\", () => {\n      const yaml = `\nname: test\nvalue: 123\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates nested objects\", () => {\n      const yaml = `\ndatabase:\n  host: localhost\n  port: 5432\n  credentials:\n    username: admin\n    password: secret\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates lists\", () => {\n      const yaml = `\nitems:\n  - apple\n  - banana\n  - cherry\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates list of objects\", () => {\n      const yaml = `\nusers:\n  - name: Alice\n    age: 30\n  - name: Bob\n    age: 25\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates quoted strings\", () => {\n      const yaml = `\nsingle: 'single quoted'\ndouble: \"double quoted\"\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates multiline strings with |\", () => {\n      const yaml = `\ndescription: |\n  This is a multiline\n  string that preserves\n  newlines.\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates multiline strings with >\", () => {\n      const yaml = `\ndescription: >\n  This is a folded\n  multiline string.\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"handles trailing whitespace\", () => {\n      const yaml = \"key: value   \\n\";\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"handles inline comments\", () => {\n      const yaml = `\nname: test # this is a comment\nvalue: 123\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n  });\n\n  describe(\"multi-document YAML\", () => {\n    test(\"validates multi-document YAML with ---\", () => {\n      const yaml = `---\nname: doc1\n---\nname: doc2\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates multi-document YAML with ... and ---\", () => {\n      const yaml = `\nname: doc1\n...\n---\nname: doc2\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"validates empty documents between separators\", () => {\n      const yaml = `---\n---\nname: doc2\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"detects bad indentation\", () => {\n      const yaml = `\nkey:\n value1: a\n  value2: b\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toBeTruthy();\n    });\n\n    test(\"detects missing colon in key-value\", () => {\n      const yaml = `\nname test\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"detects unclosed single quotes\", () => {\n      const yaml = `\nname: 'unclosed string\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"detects unclosed double quotes\", () => {\n      const yaml = `\nname: \"unclosed string\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"detects duplicate keys\", () => {\n      const yaml = `\nname: first\nname: second\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"detects tabs in indentation\", () => {\n      const yaml = `\nkey:\n\\tvalue: test\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n\n    test(\"returns error with line number\", () => {\n      const yaml = `\nvalid: yes\ninvalid key here\n`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBeGreaterThan(0);\n    });\n\n    test(\"returns error with snippet when available\", () => {\n      const yaml = `name: 'unclosed`;\n      const result = parseYaml(yaml);\n      expect(result.valid).toBe(false);\n      // Snippet may or may not be available depending on parser\n      expect(result.errors[0].message).toBeTruthy();\n    });\n  });\n});\n"
      },
      "source": "assistant"
