        "content": "/**\n * Error and success message formatter for the YAML validator command.\n */\n\nimport type { ValidationResult, YamlError } from \"./types\";\n\n/**\n * Format a success message for a validated file.\n *\n * @param source - The filename or \"stdin\"\n * @returns Formatted success message\n */\nexport function formatSuccess(source: string): string {\n  return `${source}: OK`;\n}\n\n/**\n * Format a failure message for a file with validation errors.\n *\n * @param source - The filename or \"stdin\"\n * @returns Formatted failure header\n */\nexport function formatFailure(source: string): string {\n  return `${source}: FAILED`;\n}\n\n/**\n * Format a single YAML error with line, column, message, and optional snippet.\n *\n * @param error - The YAML error to format\n * @returns Formatted error message lines\n */\nexport function formatError(error: YamlError): string {\n  const lines: string[] = [];\n\n  // Format position info: \"  Line X, Column Y: message\" or \"  Line X: message\"\n  const position = error.column\n    ? `Line ${error.line}, Column ${error.column}`\n    : `Line ${error.line}`;\n  lines.push(`  ${position}: ${error.message}`);\n\n  // Add snippet with caret if available\n  if (error.snippet !== undefined) {\n    lines.push(`    > ${error.snippet}`);\n\n    // Add caret pointing to the error position\n    if (error.column !== undefined && error.column > 0) {\n      // Offset: 4 spaces indent + \"> \" prefix + (column - 1) spaces\n      const caretOffset = 4 + 2 + (error.column - 1);\n      lines.push(\" \".repeat(caretOffset) + \"^\");\n    }\n  }\n\n  return lines.join(\"\\n\");\n}\n\n/**\n * Format a complete validation result including all errors.\n *\n * @param result - The validation result to format\n * @returns Object with stdout and stderr content\n */\nexport function formatResult(result: ValidationResult): {\n  stdout: string;\n  stderr: string;\n} {\n  if (result.valid) {\n    return {\n      stdout: formatSuccess(result.source),\n      stderr: \"\",\n    };\n  }\n\n  const errorLines: string[] = [formatFailure(result.source)];\n  for (const error of result.errors) {\n    errorLines.push(formatError(error));\n  }\n\n  return {\n    stdout: \"\",\n    stderr: errorLines.join(\"\\n\"),\n  };\n}\n\n/**\n * Format a batch summary for multiple file validations.\n *\n * @param total - Total number of files validated\n * @param passed - Number of files that passed validation\n * @param failed - Number of files that failed validation\n * @returns Formatted batch summary\n */\nexport function formatBatchSummary(\n  total: number,\n  passed: number,\n  failed: number\n): string {\n  return `Validated ${total} files: ${passed} passed, ${failed} failed`;\n}\n\n/**\n * Format all validation results for output.\n *\n * @param results - Array of validation results\n * @returns Object with combined stdout and stderr content\n */\nexport function formatResults(results: ValidationResult[]): {\n  stdout: string;\n  stderr: string;\n} {\n  const stdoutLines: string[] = [];\n  const stderrLines: string[] = [];\n\n  let passed = 0;\n  let failed = 0;\n\n  for (const result of results) {\n    const formatted = formatResult(result);\n    if (formatted.stdout) {\n      stdoutLines.push(formatted.stdout);\n    }\n    if (formatted.stderr) {\n      stderrLines.push(formatted.stderr);\n    }\n\n    if (result.valid) {\n      passed++;\n    } else {\n      failed++;\n    }\n  }\n\n  // Add batch summary if more than one file was validated\n  if (results.length > 1) {\n    stdoutLines.push(formatBatchSummary(results.length, passed, failed));\n  }\n\n  return {\n    stdout: stdoutLines.join(\"\\n\"),\n    stderr: stderrLines.join(\"\\n\"),\n  };\n}\n\n/**\n * Write success/info messages to stdout.\n *\n * @param message - The message to write\n */\nexport function writeStdout(message: string): void {\n  if (message) {\n    console.log(message);\n  }\n}\n\n/**\n * Write error messages to stderr.\n *\n * @param message - The message to write\n */\nexport function writeStderr(message: string): void {\n  if (message) {\n    console.error(message);\n  }\n}\n\n/**\n * Output all validation results to stdout and stderr.\n *\n * @param results - Array of validation results\n */\nexport function outputResults(results: ValidationResult[]): void {\n  const { stdout, stderr } = formatResults(results);\n  writeStderr(stderr);\n  writeStdout(stdout);\n}\n"
