        "file_path": "/private/tmp/rp1-evals/17773350/workspace/.rp1/work/worktrees/feature-yaml-validator/src/commands/yaml-validate/formatter.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport {\n  formatSuccess,\n  formatFailure,\n  formatError,\n  formatResult,\n  formatBatchSummary,\n  formatResults,\n} from \"./formatter\";\nimport type { YamlError, ValidationResult } from \"./types\";\n\ndescribe(\"formatSuccess\", () => {\n  test(\"formats success message for file\", () => {\n    expect(formatSuccess(\"config.yaml\")).toBe(\"config.yaml: OK\");\n  });\n\n  test(\"formats success message for stdin\", () => {\n    expect(formatSuccess(\"stdin\")).toBe(\"stdin: OK\");\n  });\n});\n\ndescribe(\"formatFailure\", () => {\n  test(\"formats failure message for file\", () => {\n    expect(formatFailure(\"config.yaml\")).toBe(\"config.yaml: FAILED\");\n  });\n\n  test(\"formats failure message for stdin\", () => {\n    expect(formatFailure(\"stdin\")).toBe(\"stdin: FAILED\");\n  });\n});\n\ndescribe(\"formatError\", () => {\n  test(\"formats error with line and message\", () => {\n    const error: YamlError = {\n      line: 5,\n      message: \"Unexpected token\",\n    };\n    const formatted = formatError(error);\n    expect(formatted).toContain(\"Line 5\");\n    expect(formatted).toContain(\"Unexpected token\");\n  });\n\n  test(\"formats error with line, column, and message\", () => {\n    const error: YamlError = {\n      line: 5,\n      column: 10,\n      message: \"Unexpected token\",\n    };\n    const formatted = formatError(error);\n    expect(formatted).toContain(\"Line 5\");\n    expect(formatted).toContain(\"Column 10\");\n    expect(formatted).toContain(\"Unexpected token\");\n  });\n\n  test(\"includes snippet when provided\", () => {\n    const error: YamlError = {\n      line: 5,\n      message: \"Unexpected token\",\n      snippet: \"  invalid: yaml here\",\n    };\n    const formatted = formatError(error);\n    expect(formatted).toContain(\"invalid: yaml here\");\n    expect(formatted).toContain(\">\");\n  });\n\n  test(\"includes caret when column and snippet provided\", () => {\n    const error: YamlError = {\n      line: 5,\n      column: 3,\n      message: \"Unexpected token\",\n      snippet: \"  invalid\",\n    };\n    const formatted = formatError(error);\n    expect(formatted).toContain(\"^\");\n  });\n});\n\ndescribe(\"formatResult\", () => {\n  test(\"returns stdout for valid result\", () => {\n    const result: ValidationResult = {\n      source: \"config.yaml\",\n      valid: true,\n      errors: [],\n    };\n    const formatted = formatResult(result);\n    expect(formatted.stdout).toBe(\"config.yaml: OK\");\n    expect(formatted.stderr).toBe(\"\");\n  });\n\n  test(\"returns stderr for invalid result\", () => {\n    const result: ValidationResult = {\n      source: \"config.yaml\",\n      valid: false,\n      errors: [\n        {\n          line: 5,\n          message: \"Syntax error\",\n        },\n      ],\n    };\n    const formatted = formatResult(result);\n    expect(formatted.stdout).toBe(\"\");\n    expect(formatted.stderr).toContain(\"config.yaml: FAILED\");\n    expect(formatted.stderr).toContain(\"Line 5\");\n    expect(formatted.stderr).toContain(\"Syntax error\");\n  });\n\n  test(\"includes all errors in stderr\", () => {\n    const result: ValidationResult = {\n      source: \"config.yaml\",\n      valid: false,\n      errors: [\n        { line: 5, message: \"First error\" },\n        { line: 10, message: \"Second error\" },\n      ],\n    };\n    const formatted = formatResult(result);\n    expect(formatted.stderr).toContain(\"First error\");\n    expect(formatted.stderr).toContain(\"Second error\");\n  });\n});\n\ndescribe(\"formatBatchSummary\", () => {\n  test(\"formats batch summary correctly\", () => {\n    const summary = formatBatchSummary(5, 3, 2);\n    expect(summary).toBe(\"Validated 5 files: 3 passed, 2 failed\");\n  });\n\n  test(\"formats summary with all passed\", () => {\n    const summary = formatBatchSummary(3, 3, 0);\n    expect(summary).toBe(\"Validated 3 files: 3 passed, 0 failed\");\n  });\n\n  test(\"formats summary with all failed\", () => {\n    const summary = formatBatchSummary(2, 0, 2);\n    expect(summary).toBe(\"Validated 2 files: 0 passed, 2 failed\");\n  });\n});\n\ndescribe(\"formatResults\", () => {\n  test(\"formats single valid result without summary\", () => {\n    const results: ValidationResult[] = [\n      { source: \"config.yaml\", valid: true, errors: [] },\n    ];\n    const formatted = formatResults(results);\n    expect(formatted.stdout).toBe(\"config.yaml: OK\");\n    expect(formatted.stderr).toBe(\"\");\n    expect(formatted.stdout).not.toContain(\"Validated\");\n  });\n\n  test(\"formats single invalid result without summary\", () => {\n    const results: ValidationResult[] = [\n      {\n        source: \"config.yaml\",\n        valid: false,\n        errors: [{ line: 1, message: \"Error\" }],\n      },\n    ];\n    const formatted = formatResults(results);\n    expect(formatted.stdout).toBe(\"\");\n    expect(formatted.stderr).toContain(\"config.yaml: FAILED\");\n    expect(formatted.stdout).not.toContain(\"Validated\");\n  });\n\n  test(\"formats multiple results with summary\", () => {\n    const results: ValidationResult[] = [\n      { source: \"config.yaml\", valid: true, errors: [] },\n      { source: \"settings.yaml\", valid: true, errors: [] },\n    ];\n    const formatted = formatResults(results);\n    expect(formatted.stdout).toContain(\"config.yaml: OK\");\n    expect(formatted.stdout).toContain(\"settings.yaml: OK\");\n    expect(formatted.stdout).toContain(\"Validated 2 files: 2 passed, 0 failed\");\n  });\n\n  test(\"formats mixed results with summary\", () => {\n    const results: ValidationResult[] = [\n      { source: \"config.yaml\", valid: true, errors: [] },\n      {\n        source: \"settings.yaml\",\n        valid: false,\n        errors: [{ line: 1, message: \"Error\" }],\n      },\n    ];\n    const formatted = formatResults(results);\n    expect(formatted.stdout).toContain(\"config.yaml: OK\");\n    expect(formatted.stderr).toContain(\"settings.yaml: FAILED\");\n    expect(formatted.stdout).toContain(\"Validated 2 files: 1 passed, 1 failed\");\n  });\n});\n"
