        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { validateFile, validateFiles, allValid } from \"./validator\";\nimport { mkdtemp, rmdir, writeFile, mkdir } from \"fs/promises\";\nimport { join } from \"path\";\nimport { tmpdir } from \"os\";\n\ndescribe(\"validateFile\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"yaml-validator-test-\"));\n  });\n\n  afterAll(async () => {\n    await rmdir(tempDir, { recursive: true });\n  });\n\n  test(\"validates valid YAML file\", async () => {\n    const filePath = join(tempDir, \"valid.yaml\");\n    await writeFile(filePath, \"name: test\\nvalue: 123\\n\");\n\n    const result = await validateFile(filePath);\n    expect(result.source).toBe(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toEqual([]);\n  });\n\n  test(\"validates invalid YAML file\", async () => {\n    const filePath = join(tempDir, \"invalid.yaml\");\n    await writeFile(filePath, \"name: 'unclosed string\\n\");\n\n    const result = await validateFile(filePath);\n    expect(result.source).toBe(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors.length).toBeGreaterThan(0);\n  });\n\n  test(\"handles non-existent file\", async () => {\n    const filePath = join(tempDir, \"nonexistent.yaml\");\n\n    const result = await validateFile(filePath);\n    expect(result.source).toBe(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors.length).toBe(1);\n    expect(result.errors[0].message).toContain(\"File not found\");\n  });\n\n  test(\"validates empty file as valid\", async () => {\n    const filePath = join(tempDir, \"empty.yaml\");\n    await writeFile(filePath, \"\");\n\n    const result = await validateFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toEqual([]);\n  });\n\n  test(\"validates comments-only file as valid\", async () => {\n    const filePath = join(tempDir, \"comments.yaml\");\n    await writeFile(filePath, \"# Just a comment\\n# Another comment\\n\");\n\n    const result = await validateFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toEqual([]);\n  });\n\n  test(\"detects binary files\", async () => {\n    const filePath = join(tempDir, \"binary.yaml\");\n    const binaryContent = Buffer.from([\n      0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00,\n    ]);\n    await writeFile(filePath, binaryContent);\n\n    const result = await validateFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors[0].message).toContain(\"binary\");\n  });\n\n  test(\"validates file with nested structure\", async () => {\n    const filePath = join(tempDir, \"nested.yaml\");\n    await writeFile(\n      filePath,\n      `\ndatabase:\n  host: localhost\n  port: 5432\n  credentials:\n    username: admin\n    password: secret\n`\n    );\n\n    const result = await validateFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toEqual([]);\n  });\n\n  test(\"validates file with lists\", async () => {\n    const filePath = join(tempDir, \"list.yaml\");\n    await writeFile(\n      filePath,\n      `\nitems:\n  - apple\n  - banana\n  - cherry\n`\n    );\n\n    const result = await validateFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toEqual([]);\n  });\n});\n\ndescribe(\"validateFiles\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"yaml-validator-batch-test-\"));\n  });\n\n  afterAll(async () => {\n    await rmdir(tempDir, { recursive: true });\n  });\n\n  test(\"validates multiple valid files\", async () => {\n    const file1 = join(tempDir, \"batch-valid1.yaml\");\n    const file2 = join(tempDir, \"batch-valid2.yaml\");\n    await writeFile(file1, \"name: doc1\\n\");\n    await writeFile(file2, \"name: doc2\\n\");\n\n    const results = await validateFiles([file1, file2]);\n    expect(results.length).toBe(2);\n    expect(results[0].valid).toBe(true);\n    expect(results[1].valid).toBe(true);\n  });\n\n  test(\"validates mixed valid and invalid files\", async () => {\n    const validFile = join(tempDir, \"batch-mixed-valid.yaml\");\n    const invalidFile = join(tempDir, \"batch-mixed-invalid.yaml\");\n    await writeFile(validFile, \"name: valid\\n\");\n    await writeFile(invalidFile, \"name: 'unclosed\\n\");\n\n    const results = await validateFiles([validFile, invalidFile]);\n    expect(results.length).toBe(2);\n    expect(results[0].valid).toBe(true);\n    expect(results[1].valid).toBe(false);\n  });\n\n  test(\"handles empty file list\", async () => {\n    const results = await validateFiles([]);\n    expect(results).toEqual([]);\n  });\n\n  test(\"preserves order of results\", async () => {\n    const file1 = join(tempDir, \"batch-order1.yaml\");\n    const file2 = join(tempDir, \"batch-order2.yaml\");\n    const file3 = join(tempDir, \"batch-order3.yaml\");\n    await writeFile(file1, \"name: first\\n\");\n    await writeFile(file2, \"name: second\\n\");\n    await writeFile(file3, \"name: third\\n\");\n\n    const results = await validateFiles([file1, file2, file3]);\n    expect(results[0].source).toBe(file1);\n    expect(results[1].source).toBe(file2);\n    expect(results[2].source).toBe(file3);\n  });\n});\n\ndescribe(\"allValid\", () => {\n  test(\"returns true when all results are valid\", () => {\n    const results = [\n      { source: \"a.yaml\", valid: true, errors: [] },\n      { source: \"b.yaml\", valid: true, errors: [] },\n    ];\n    expect(allValid(results)).toBe(true);\n  });\n\n  test(\"returns false when any result is invalid\", () => {\n    const results = [\n      { source: \"a.yaml\", valid: true, errors: [] },\n      { source: \"b.yaml\", valid: false, errors: [{ line: 1, message: \"Error\" }] },\n    ];\n    expect(allValid(results)).toBe(false);\n  });\n\n  test(\"returns true for empty results array\", () => {\n    expect(allValid([])).toBe(true);\n  });\n\n  test(\"returns false when all results are invalid\", () => {\n    const results = [\n      { source: \"a.yaml\", valid: false, errors: [{ line: 1, message: \"Error\" }] },\n      { source: \"b.yaml\", valid: false, errors: [{ line: 1, message: \"Error\" }] },\n    ];\n    expect(allValid(results)).toBe(false);\n  });\n});\n"
