        "content": "/**\n * CLI argument parser for the YAML validator command.\n */\n\nimport type { ParsedArgs } from \"./types\";\n\n/**\n * Parse command-line arguments into a structured object.\n *\n * @param argv - The process.argv array (typically starting from index 2)\n * @returns Parsed arguments with flags and file paths\n */\nexport function parseArgs(argv: string[]): ParsedArgs {\n  const result: ParsedArgs = {\n    files: [],\n    help: false,\n    stdin: false,\n    version: false,\n  };\n\n  for (const arg of argv) {\n    switch (arg) {\n      case \"--help\":\n      case \"-h\":\n        result.help = true;\n        break;\n      case \"--version\":\n      case \"-v\":\n        result.version = true;\n        break;\n      case \"--stdin\":\n      case \"-\":\n        result.stdin = true;\n        break;\n      default:\n        // Any other argument is treated as a file path\n        if (!arg.startsWith(\"-\")) {\n          result.files.push(arg);\n        }\n        // Unknown flags are silently ignored (could be future options)\n        break;\n    }\n  }\n\n  return result;\n}\n\n/**\n * Check if the parsed arguments indicate that help should be shown.\n * This includes when no arguments are provided and stdin is not being used.\n *\n * @param args - Parsed arguments\n * @param hasStdinInput - Whether stdin has input available\n * @returns True if usage hint should be shown\n */\nexport function shouldShowUsageHint(\n  args: ParsedArgs,\n  hasStdinInput: boolean\n): boolean {\n  // Show usage hint if no files provided, stdin mode not requested, and no stdin input\n  return args.files.length === 0 && !args.stdin && !hasStdinInput;\n}\n\n/**\n * Get the help text for the validator command.\n */\nexport function getHelpText(): string {\n  return `yaml-validate - Validate YAML file syntax\n\nUSAGE:\n    bun run validate [OPTIONS] [FILES...]\n    cat file.yaml | bun run validate --stdin\n\nOPTIONS:\n    -h, --help      Show this help message\n    -v, --version   Show version information\n    --stdin, -      Read YAML from stdin\n\nEXAMPLES:\n    bun run validate config.yaml\n    bun run validate config.yaml settings.yaml\n    cat config.yaml | bun run validate --stdin\n\nEXIT CODES:\n    0   All files validated successfully\n    1   One or more validation failures\n    2   Usage or argument error`;\n}\n\n/**\n * Get the version string for the validator command.\n */\nexport function getVersionText(): string {\n  return \"yaml-validate 1.0.0\";\n}\n"
      },
