        "content": "/**\n * CLI entry point for the YAML validator command.\n * Orchestrates argument parsing, validation, and output formatting.\n */\n\nimport { parseArgs, shouldShowUsageHint, getHelpText, getVersionText } from \"./args\";\nimport { validate, allValid } from \"./validator\";\nimport { outputResults, writeStdout, writeStderr } from \"./formatter\";\n\n/** Exit code for successful validation */\nconst EXIT_SUCCESS = 0;\n/** Exit code for validation failures */\nconst EXIT_VALIDATION_ERROR = 1;\n/** Exit code for usage/argument errors */\nconst EXIT_USAGE_ERROR = 2;\n\n/**\n * Check if stdin has input available (is not a TTY).\n */\nfunction hasStdinInput(): boolean {\n  return !process.stdin.isTTY;\n}\n\n/**\n * Main CLI entry point.\n */\nasync function main(): Promise<number> {\n  const args = parseArgs(process.argv.slice(2));\n\n  if (args.help) {\n    writeStdout(getHelpText());\n    return EXIT_SUCCESS;\n  }\n\n  if (args.version) {\n    writeStdout(getVersionText());\n    return EXIT_SUCCESS;\n  }\n\n  const stdinAvailable = hasStdinInput();\n\n  if (shouldShowUsageHint(args, stdinAvailable)) {\n    writeStderr(\"Error: No input files specified\");\n    writeStderr(\"\");\n    writeStderr(getHelpText());\n    return EXIT_USAGE_ERROR;\n  }\n\n  const useStdin = args.stdin || (args.files.length === 0 && stdinAvailable);\n\n  if (!useStdin && args.files.length === 0) {\n    writeStderr(\"Error: No input files specified\");\n    return EXIT_USAGE_ERROR;\n  }\n\n  const results = await validate(args.files, useStdin);\n\n  if (results.length === 0) {\n    writeStderr(\"Error: No input to validate\");\n    return EXIT_USAGE_ERROR;\n  }\n\n  outputResults(results);\n\n  return allValid(results) ? EXIT_SUCCESS : EXIT_VALIDATION_ERROR;\n}\n\nmain()\n  .then((exitCode) => {\n    process.exit(exitCode);\n  })\n  .catch((error) => {\n    writeStderr(`Unexpected error: ${error instanceof Error ? error.message : String(error)}`);\n    process.exit(EXIT_USAGE_ERROR);\n  });\n"
