else res[key] = null;\n      } else {\n        res[key] = this.parseScalar(after);\n      }\n    }\n    return res;\n  }\n\n  private parseList(baseIndent: number): YAMLValue[] {\n    const res: YAMLValue[] = [];\n    while (this.pos < this.lines.length) {\n      const line = this.lines[this.pos];\n      if (this.empty(line)) { this.pos++; continue; }\n      const t = line.trim(), ind = this.indent(line);\n      if (t === '---' || t === '...' || ind < baseIndent) break;\n      if (ind > baseIndent || !(t.startsWith('- ') || t === '-')) break;\n\n      const after = t.slice(1).trim();\n      this.pos++;\n\n      if (after === '') {\n        const next = this.peekNonEmpty();\n        if (next && this.indent(next) > ind) res.push(this.parseValue(this.indent(next)));\n        else res.push(null);\n      } else if (this.hasColon(after)) {\n        // Inline map in list item\n        const ci = this.colonIdx(after);\n        const k = after.slice(0, ci).trim(), v = after.slice(ci + 1).trim();\n        const map: { [k: string]: YAMLValue } = { [k]: v === '' ? this.parseNestedMapValue(ind + 2) : this.parseScalar(v) };\n        // Check for continuation of this inline map\n        while (this.pos < this.lines.length) {\n          const nl = this.lines[this.pos];\n          if (this.empty(nl)) { this.pos++; continue; }\n          const nind = this.indent(nl), nt = nl.trim();\n          if (nind <= ind || nt.startsWith('- ')) break;\n          if (this.hasColon(nt)) {\n            const nci = this.colonIdx(nt);\n            const nk = nt.slice(0, nci).trim(), nv = nt.slice(nci + 1).trim();\n            this.pos++;\n            map[nk] = nv === '' ? this.parseNestedMapValue(nind) : this.parseScalar(nv);\n          } else break;\n        }\n        res.push(map);\n      } else {\n        res.push(this.parseScalar(after));\n      }\n    }\n    return res;\n  }\n\n  private parseNestedMapValue(parentIndent: number): YAMLValue {\n    const next = this.peekNonEmpty();\n    if (next 