        "content": "/**\n * TypeScript interfaces and types for the YAML validator command.\n */\n\n/**\n * Parsed command-line arguments.\n */\nexport interface ParsedArgs {\n  /** File paths to validate */\n  files: string[];\n  /** Whether --help or -h flag was provided */\n  help: boolean;\n  /** Whether --stdin or - flag was provided */\n  stdin: boolean;\n  /** Whether --version or -v flag was provided */\n  version: boolean;\n}\n\n/**\n * Result of validating a single YAML source.\n */\nexport interface ValidationResult {\n  /** Filename or \"stdin\" */\n  source: string;\n  /** Whether the YAML is valid */\n  valid: boolean;\n  /** Array of errors found (empty if valid) */\n  errors: YamlError[];\n}\n\n/**\n * A single YAML syntax error.\n */\nexport interface YamlError {\n  /** Line number where the error was detected (1-indexed) */\n  line: number;\n  /** Column number where the error was detected (1-indexed, optional) */\n  column?: number;\n  /** Human-readable error message */\n  message: string;\n  /** Source code snippet showing the error context (optional) */\n  snippet?: string;\n}\n"
