        "file_path": "/private/tmp/rp1-evals/17773350/workspace/.rp1/work/worktrees/feature-yaml-validator/src/commands/yaml-validate/validator.ts",
        "content": "/**\n * Validation orchestration for the YAML validator command.\n * Coordinates file reading, stdin handling, and YAML parsing.\n */\n\nimport { parseYaml } from \"./yaml-parser\";\nimport type { ValidationResult, YamlError } from \"./types\";\n\n/**\n * Validate YAML content from a file path.\n *\n * @param filePath - Path to the YAML file to validate\n * @returns Validation result with source, validity, and any errors\n */\nexport async function validateFile(filePath: string): Promise<ValidationResult> {\n  try {\n    const file = Bun.file(filePath);\n    const exists = await file.exists();\n\n    if (!exists) {\n      return {\n        source: filePath,\n        valid: false,\n        errors: [\n          {\n            line: 0,\n            message: `File not found: ${filePath}`,\n          },\n        ],\n      };\n    }\n\n    // Check if the file appears to be binary\n    const isBinary = await isFileBinary(file);\n    if (isBinary) {\n      return {\n        source: filePath,\n        valid: false,\n        errors: [\n          {\n            line: 0,\n            message: \"Cannot validate binary file\",\n          },\n        ],\n      };\n    }\n\n    const content = await file.text();\n    const parseResult = parseYaml(content, filePath);\n\n    return {\n      source: filePath,\n      valid: parseResult.valid,\n      errors: parseResult.errors,\n    };\n  } catch (error) {\n    const errorMessage =\n      error instanceof Error ? error.message : String(error);\n    return {\n      source: filePath,\n      valid: false,\n      errors: [\n        {\n          line: 0,\n          message: `Error reading file: ${errorMessage}`,\n        },\n      ],\n    };\n  }\n}\n\n/**\n * Validate YAML content from stdin.\n *\n * @returns Validation result with source as \"stdin\"\n */\nexport async function validateStdin(): Promise<ValidationResult> {\n  try {\n    const content = await readStdin();\n\n    if (content === null) {\n      return {\n        source: \"stdin\",\n        valid: false,\n        errors: [\n          {\n            line: 0,\n            message: \"No input received from stdin\",\n          },\n        ],\n      };\n    }\n\n    const parseResult = parseYaml(content, \"stdin\");\n\n    return {\n      source: \"stdin\",\n      valid: parseResult.valid,\n      errors: parseResult.errors,\n    };\n  } catch (error) {\n    const errorMessage =\n      error instanceof Error ? error.message : String(error);\n    return {\n      source: \"stdin\",\n      valid: false,\n      errors: [\n        {\n          line: 0,\n          message: `Error reading stdin: ${errorMessage}`,\n        },\n      ],\n    };\n  }\n}\n\n/**\n * Read content from stdin.\n *\n * @returns The stdin content as a string, or null if no input\n */\nasync function readStdin(): Promise<string | null> {\n  const chunks: Uint8Array[] = [];\n  const reader = Bun.stdin.stream().getReader();\n\n  try {\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      if (value) {\n        chunks.push(value);\n      }\n    }\n  } finally {\n    reader.releaseLock();\n  }\n\n  if (chunks.length === 0) {\n    return null;\n  }\n\n  // Combine chunks and decode as UTF-8\n  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);\n  const combined = new Uint8Array(totalLength);\n  let offset = 0;\n  for (const chunk of chunks) {\n    combined.set(chunk, offset);\n    offset += chunk.length;\n  }\n\n  return new TextDecoder(\"utf-8\").decode(combined);\n}\n\n/**\n * Check if a file appears to be binary (non-text).\n * Uses a simple heuristic: checks for null bytes in the first 8KB.\n *\n * @param file - The Bun file object to check\n * @returns True if the file appears to be binary\n */\nasync function isFileBinary(file: ReturnType<typeof Bun.file>): Promise<boolean> {\n  try {\n    // Read first 8KB to check for binary content\n    const sampleSize = 8192;\n    const fileSize = file.size;\n    const readSize = Math.min(sampleSize, fileSize);\n\n    if (readSize === 0) {\n      return false; // Empty files are not binary\n    }\n\n    const buffer = await file.slice(0, readSize).arrayBuffer();\n    const bytes = new Uint8Array(buffer);\n\n    // Check for null bytes (common indicator of binary content)\n    for (let i = 0; i < bytes.length; i++) {\n      if (bytes[i] === 0) {\n        return true;\n      }\n    }\n\n    return false;\n  } catch {\n    // If we can't read the file, assume it's not binary\n    return false;\n  }\n}\n\n/**\n * Validate multiple YAML files.\n *\n * @param filePaths - Array of file paths to validate\n * @returns Array of validation results\n */\nexport async function validateFiles(\n  filePaths: string[]\n): Promise<ValidationResult[]> {\n  const results: ValidationResult[] = [];\n\n  for (const filePath of filePaths) {\n    const result = await validateFile(filePath);\n    results.push(result);\n  }\n\n  return results;\n}\n\n/**\n * Main validation function that orchestrates file and stdin validation.\n *\n * @param filePaths - Array of file paths to validate\n * @param useStdin - Whether to read from stdin\n * @returns Array of validation results\n */\nexport async function validate(\n  filePaths: string[],\n  useStdin: boolean\n): Promise<ValidationResult[]> {\n  const results: ValidationResult[] = [];\n\n  // Validate stdin if requested\n  if (useStdin) {\n    const stdinResult = await validateStdin();\n    results.push(stdinResult);\n  }\n\n  // Validate files\n  if (filePaths.length > 0) {\n    const fileResults = await validateFiles(filePaths);\n    results.push(...fileResults);\n  }\n\n  return results;\n}\n\n/**\n * Check if all validation results indicate success.\n *\n * @param results - Array of validation results\n * @returns True if all results are valid\n */\nexport function allValid(results: ValidationResult[]): boolean {\n  return results.every((result) => result.valid);\n}\n"
