/**
 * CLI entry point for the YAML validator command.
 * Orchestrates argument parsing, validation, and output formatting.
 */

import { parseArgs, shouldShowUsageHint, getHelpText, getVersionText } from "./args";
import { validate, allValid } from "./validator";
import { outputResults, writeStdout, writeStderr } from "./formatter";

/** Exit code for successful validation */
const EXIT_SUCCESS = 0;
/** Exit code for validation failures */
const EXIT_VALIDATION_ERROR = 1;
/** Exit code for usage/argument errors */
const EXIT_USAGE_ERROR = 2;

/**
 * Check if stdin has input available (is not a TTY).
 */
function hasStdinInput(): boolean {
  return !process.stdin.isTTY;
}

/**
 * Main CLI entry point.
 */
async function main(): Promise<number> {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) {
    writeStdout(getHelpText());
    return EXIT_SUCCESS;
  }

  if (args.version) {
    writeStdout(getVersionText());
    return EXIT_SUCCESS;
  }

  const stdinAvailable = hasStdinInput();

  if (shouldShowUsageHint(args, stdinAvailable)) {
    writeStderr("Error: No input files specified");
    writeStderr("");
    writeStderr(getHelpText());
    return EXIT_USAGE_ERROR;
  }

  const useStdin = args.stdin || (args.files.length === 0 && stdinAvailable);

  if (!useStdin && args.files.length === 0) {
    writeStderr("Error: No input files specified");
    return EXIT_USAGE_ERROR;
  }

  const results = await validate(args.files, useStdin);

  if (results.length === 0) {
    writeStderr("Error: No input to validate");
    return EXIT_USAGE_ERROR;
  }

  outputResults(results);

  return allValid(results) ? EXIT_SUCCESS : EXIT_VALIDATION_ERROR;
}

main()
  .then((exitCode) => {
    process.exit(exitCode);
  })
  .catch((error) => {
    writeStderr(`Unexpected error: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(EXIT_USAGE_ERROR);
  });

import { describe, expect, test } from "bun:test";
import {
  parseArgs,
  shouldShowUsageHint,
  getHelpText,
  getVersionText,
} from "./args";

describe("parseArgs", () => {
  test("returns empty result for no arguments", () => {
    const result = parseArgs([]);
    expect(result).toEqual({
      files: [],
      help: false,
      stdin: false,
      version: false,
    });
  });

  test("parses --help flag", () => {
    const result = parseArgs(["--help"]);
    expect(result.help).toBe(true);
  });

  test("parses -h flag", () => {
    const result = parseArgs(["-h"]);
    expect(result.help).toBe(true);
  });

  test("parses --version flag", () => {
    const result = parseArgs(["--version"]);
    expect(result.version).toBe(true);
  });

  test("parses -v flag", () => {
    const result = parseArgs(["-v"]);
    expect(result.version).toBe(true);
  });

  test("parses --stdin flag", () => {
    const result = parseArgs(["--stdin"]);
    expect(result.stdin).toBe(true);
  });

  test("parses - flag as stdin", () => {
    const result = parseArgs(["-"]);
    expect(result.stdin).toBe(true);
  });

  test("collects file paths", () => {
    const result = parseArgs(["config.yaml", "settings.yaml"]);
    expect(result.files).toEqual(["config.yaml", "settings.yaml"]);
  });

  test("handles mixed flags and files", () => {
    const result = parseArgs(["--stdin", "config.yaml", "-v"]);
    expect(result.stdin).toBe(true);
    expect(result.version).toBe(true);
    expect(result.files).toEqual(["config.yaml"]);
  });

  test("ignores unknown flags", () => {
    const result = parseArgs(["--unknown", "config.yaml"]);
    expect(result.files).toEqual(["config.yaml"]);
  });
});

describe("shouldShowUsageHint", () => {
  test("returns true when no files, no stdin flag, and no stdin input", () => {
    const args = { files: [], help: false, stdin: false, version: false };
    expect(shouldShowUsageHint(args, false)).toBe(true);
  });

  test("returns false when files are provided", () => {
    const args = {
      files: ["config.yaml"],
      help: false,
      stdin: false,
      version: false,
    };
    expect(shouldShowUsageHint(args, false)).toBe(false);
  });

  test("returns false when stdin flag is set", () => {
    const args = { files: [], help: false, stdin: true, version: false };
    expect(shouldShowUsageHint(args, false)).toBe(false);
  });

  test("returns false when stdin input is available", () => {
    const args = { files: [], help: false, stdin: false, version: false };
    expect(shouldShowUsageHint(args, true)).toBe(false);
  });
});

describe("getHelpText", () => {
  test("returns help text containing usage information", () => {
    const helpText = getHelpText();
    expect(helpText).toContain("yaml-validate");
    expect(helpText).toContain("USAGE");
    expect(helpText).toContain("OPTIONS");
    expect(helpText).toContain("--help");
    expect(helpText).toContain("--stdin");
    expect(helpText).toContain("EXAMPLES");
    expect(helpText).toContain("EXIT CODES");
  });
});

describe("getVersionText", () => {
  test("returns version string", () => {
    const versionText = getVersionText();
    expect(versionText).toContain("yaml-validate");
    expect(versionText).toMatch(/\d+\.\d+\.\d+/);
  });
});

import { describe, expect, test } from "bun:test";
import { parseYaml } from "./yaml-parser";

describe("parseYaml", () => {
  describe("valid YAML", () => {
    test("handles empty file", () => {
      const result = parseYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("handles whitespace-only file", () => {
      const result = parseYaml("   \n\n   ");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("handles comments-only file", () => {
      const result = parseYaml("# This is a comment\n# Another comment");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates simple key-value pairs", () => {
      const yaml = `
name: test
value: 123
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates nested objects", () => {
      const yaml = `
database:
  host: localhost
  port: 5432
  credentials:
    username: admin
    password: secret
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates lists", () => {
      const yaml = `
items:
  - apple
  - banana
  - cherry
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates list of objects", () => {
      const yaml = `
users:
  - name: Alice
    age: 30
  - name: Bob
    age: 25
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates quoted strings", () => {
      const yaml = `
single: 'single quoted'
double: "double quoted"
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates multiline strings with |", () => {
      const yaml = `
description: |
  This is a multiline
  string that preserves
  newlines.
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates multiline strings with >", () => {
      const yaml = `
description: >
  This is a folded
  multiline string.
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("handles trailing whitespace", () => {
      const yaml = "key: value   \n";
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("handles inline comments", () => {
      const yaml = `
name: test # this is a comment
value: 123
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("multi-document YAML", () => {
    test("validates multi-document YAML with ---", () => {
      const yaml = `---
name: doc1
---
name: doc2
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates multi-document YAML with ... and ---", () => {
      const yaml = `
name: doc1
...
---
name: doc2
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("validates empty documents between separators", () => {
      const yaml = `---
---
name: doc2
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("invalid YAML", () => {
    test("detects bad indentation", () => {
      const yaml = `
key:
 value1: a
  value2: b
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toBeTruthy();
    });

    test("detects missing colon in key-value", () => {
      const yaml = `
name test
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed single quotes", () => {
      const yaml = `
name: 'unclosed string
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed double quotes", () => {
      const yaml = `
name: "unclosed string
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects duplicate keys", () => {
      const yaml = `
name: first
name: second
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects tabs in indentation", () => {
      const yaml = `
key:
\tvalue: test
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("returns error with line number", () => {
      const yaml = `
valid: yes
invalid key here
`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBeGreaterThan(0);
    });

    test("returns error with snippet when available", () => {
      const yaml = `name: 'unclosed`;
      const result = parseYaml(yaml);
      expect(result.valid).toBe(false);
      // Snippet may or may not be available depending on parser
      expect(result.errors[0].message).toBeTruthy();
    });
  });
});

import { describe, expect, test } from "bun:test";
import {
  formatSuccess,
  formatFailure,
  formatError,
  formatResult,
  formatBatchSummary,
  formatResults,
} from "./formatter";
import type { YamlError, ValidationResult } from "./types";

describe("formatSuccess", () => {
  test("formats success message for file", () => {
    expect(formatSuccess("config.yaml")).toBe("config.yaml: OK");
  });

  test("formats success message for stdin", () => {
    expect(formatSuccess("stdin")).toBe("stdin: OK");
  });
});

describe("formatFailure", () => {
  test("formats failure message for file", () => {
    expect(formatFailure("config.yaml")).toBe("config.yaml: FAILED");
  });

  test("formats failure message for stdin", () => {
    expect(formatFailure("stdin")).toBe("stdin: FAILED");
  });
});

describe("formatError", () => {
  test("formats error with line and message", () => {
    const error: YamlError = {
      line: 5,
      message: "Unexpected token",
    };
    const formatted = formatError(error);
    expect(formatted).toContain("Line 5");
    expect(formatted).toContain("Unexpected token");
  });

  test("formats error with line, column, and message", () => {
    const error: YamlError = {
      line: 5,
      column: 10,
      message: "Unexpected token",
    };
    const formatted = formatError(error);
    expect(formatted).toContain("Line 5");
    expect(formatted).toContain("Column 10");
    expect(formatted).toContain("Unexpected token");
  });

  test("includes snippet when provided", () => {
    const error: YamlError = {
      line: 5,
      message: "Unexpected token",
      snippet: "  invalid: yaml here",
    };
    const formatted = formatError(error);
    expect(formatted).toContain("invalid: yaml here");
    expect(formatted).toContain(">");
  });

  test("includes caret when column and snippet provided", () => {
    const error: YamlError = {
      line: 5,
      column: 3,
      message: "Unexpected token",
      snippet: "  invalid",
    };
    const formatted = formatError(error);
    expect(formatted).toContain("^");
  });
});

describe("formatResult", () => {
  test("returns stdout for valid result", () => {
    const result: ValidationResult = {
      source: "config.yaml",
      valid: true,
      errors: [],
    };
    const formatted = formatResult(result);
    expect(formatted.stdout).toBe("config.yaml: OK");
    expect(formatted.stderr).toBe("");
  });

  test("returns stderr for invalid result", () => {
    const result: ValidationResult = {
      source: "config.yaml",
      valid: false,
      errors: [
        {
          line: 5,
          message: "Syntax error",
        },
      ],
    };
    const formatted = formatResult(result);
    expect(formatted.stdout).toBe("");
    expect(formatted.stderr).toContain("config.yaml: FAILED");
    expect(formatted.stderr).toContain("Line 5");
    expect(formatted.stderr).toContain("Syntax error");
  });

  test("includes all errors in stderr", () => {
    const result: ValidationResult = {
      source: "config.yaml",
      valid: false,
      errors: [
        { line: 5, message: "First error" },
        { line: 10, message: "Second error" },
      ],
    };
    const formatted = formatResult(result);
    expect(formatted.stderr).toContain("First error");
    expect(formatted.stderr).toContain("Second error");
  });
});

describe("formatBatchSummary", () => {
  test("formats batch summary correctly", () => {
    const summary = formatBatchSummary(5, 3, 2);
    expect(summary).toBe("Validated 5 files: 3 passed, 2 failed");
  });

  test("formats summary with all passed", () => {
    const summary = formatBatchSummary(3, 3, 0);
    expect(summary).toBe("Validated 3 files: 3 passed, 0 failed");
  });

  test("formats summary with all failed", () => {
    const summary = formatBatchSummary(2, 0, 2);
    expect(summary).toBe("Validated 2 files: 0 passed, 2 failed");
  });
});

describe("formatResults", () => {
  test("formats single valid result without summary", () => {
    const results: ValidationResult[] = [
      { source: "config.yaml", valid: true, errors: [] },
    ];
    const formatted = formatResults(results);
    expect(formatted.stdout).toBe("config.yaml: OK");
    expect(formatted.stderr).toBe("");
    expect(formatted.stdout).not.toContain("Validated");
  });

  test("formats single invalid result without summary", () => {
    const results: ValidationResult[] = [
      {
        source: "config.yaml",
        valid: false,
        errors: [{ line: 1, message: "Error" }],
      },
    ];
    const formatted = formatResults(results);
    expect(formatted.stdout).toBe("");
    expect(formatted.stderr).toContain("config.yaml: FAILED");
    expect(formatted.stdout).not.toContain("Validated");
  });

  test("formats multiple results with summary", () => {
    const results: ValidationResult[] = [
      { source: "config.yaml", valid: true, errors: [] },
      { source: "settings.yaml", valid: true, errors: [] },
    ];
    const formatted = formatResults(results);
    expect(formatted.stdout).toContain("config.yaml: OK");
    expect(formatted.stdout).toContain("settings.yaml: OK");
    expect(formatted.stdout).toContain("Validated 2 files: 2 passed, 0 failed");
  });

  test("formats mixed results with summary", () => {
    const results: ValidationResult[] = [
      { source: "config.yaml", valid: true, errors: [] },
      {
        source: "settings.yaml",
        valid: false,
        errors: [{ line: 1, message: "Error" }],
      },
    ];
    const formatted = formatResults(results);
    expect(formatted.stdout).toContain("config.yaml: OK");
    expect(formatted.stderr).toContain("settings.yaml: FAILED");
