/**
 * Pure TypeScript YAML Syntax Validator v2 - Optimized
 * DISPOSABLE CODE - For hypothesis validation only
 */

type YAMLValue = string | number | boolean | null | YAMLValue[] | { [key: string]: YAMLValue };
interface ParseResult { valid: boolean; error?: string; line?: number; documents?: YAMLValue[]; }

class YAMLValidator {
  private lines: string[] = [];
  private pos = 0;

  parse(input: string): ParseResult {
    this.lines = input.split('\n');
    this.pos = 0;
    try {
      const docs: YAMLValue[] = [];
      while (this.pos < this.lines.length) {
        const line = this.lines[this.pos], t = line.trim();
        if (!t || t.startsWith('#') || t === '---' || t === '...') { this.pos++; continue; }
        const doc = this.parseValue(0);
        if (doc !== undefined) docs.push(doc);
      }
      return { valid: true, documents: docs };
    } catch (e) { return { valid: false, error: (e as Error).message, line: this.pos + 1 }; }
  }

  private indent(line: string): number { return (line.match(/^(\s*)/) || ['', ''])[1].length; }
  private empty(line: string): boolean { const t = line.trim(); return !t || t.startsWith('#'); }

  private parseValue(minIndent: number): YAMLValue {
    while (this.pos < this.lines.length) {
      const line = this.lines[this.pos];
      if (this.empty(line)) { this.pos++; continue; }
      const t = line.trim(), ind = this.indent(line);
      if (t === '---' || t === '...') return null as unknown as YAMLValue;
      if (ind < minIndent) return null as unknown as YAMLValue;
      if (t.startsWith('- ') || t === '-') return this.parseList(ind);
      if (this.hasColon(t)) return this.parseMap(ind);
      return this.parseScalar(t);
    }
    return null as unknown as YAMLValue;
  }

  private hasColon(line: string): boolean {
    let sq = false, dq = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i], p = i > 0 ? line[i-1] : '';
      if (c === "'" && !dq && p !== '\\') sq = !sq;
      else if (c === '"' && !sq && p !== '\\') dq = !dq;
      else if (c === ':' && !sq && !dq && (i === line.length-1 || /\s/.test(line[i+1]))) return true;
    }
    if (sq) throw new Error(`Unclosed single quote at line ${this.pos + 1}`);
    if (dq) throw new Error(`Unclosed double quote at line ${this.pos + 1}`);
    return false;
  }

  private colonIdx(line: string): number {
    let sq = false, dq = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i], p = i > 0 ? line[i-1] : '';
      if (c === "'" && !dq && p !== '\\') sq = !sq;
      else if (c === '"' && !sq && p !== '\\') dq = !dq;
      else if (c === ':' && !sq && !dq && (i === line.length-1 || /\s/.test(line[i+1]))) return i;
    }
    return -1;
  }

  private parseMap(baseIndent: number): { [k: string]: YAMLValue } {
    const res: { [k: string]: YAMLValue } = {};
    while (this.pos < this.lines.length) {
      const line = this.lines[this.pos];
      if (this.empty(line)) { this.pos++; continue; }
      const t = line.trim(), ind = this.indent(line);
      if (t === '---' || t === '...' || ind < baseIndent) break;
      if (ind > baseIndent) break;
      if (t.startsWith('- ')) break;

      const ci = this.colonIdx(t);
      if (ci === -1) throw new Error(`Missing colon at line ${this.pos + 1}`);

      const key = t.slice(0, ci).trim(), after = t.slice(ci + 1).trim();
      if (!key) throw new Error(`Empty key at line ${this.pos + 1}`);
      this.pos++;

      if (after === '|' || after === '|-' || after === '|+') {
        res[key] = this.parseBlock(baseIndent, true);
      } else if (after === '>' || after === '>-' || after === '>+') {
        res[key] = this.parseBlock(baseIndent, false);
      } else if (after === '') {
        const next = this.peekNonEmpty();
        if (next && this.indent(next) > ind) res[key] = this.parseValue(this.indent(next));
        else res[key] = null;
      } else {
        res[key] = this.parseScalar(after);
      }
    }
    return res;
  }

  private parseList(baseIndent: number): YAMLValue[] {
    const res: YAMLValue[] = [];
    while (this.pos < this.lines.length) {
      const line = this.lines[this.pos];
      if (this.empty(line)) { this.pos++; continue; }
      const t = line.trim(), ind = this.indent(line);
      if (t === '---' || t === '...' || ind < baseIndent) break;
      if (ind > baseIndent || !(t.startsWith('- ') || t === '-')) break;

      const after = t.slice(1).trim();
      this.pos++;

      if (after === '') {
        const next = this.peekNonEmpty();
        if (next && this.indent(next) > ind) res.push(this.parseValue(this.indent(next)));
        else res.push(null);
      } else if (this.hasColon(after)) {
        // Inline map in list item
        const ci = this.colonIdx(after);
        const k = after.slice(0, ci).trim(), v = after.slice(ci + 1).trim();
        const map: { [k: string]: YAMLValue } = { [k]: v === '' ? this.parseNestedMapValue(ind + 2) : this.parseScalar(v) };
        // Check for continuation of this inline map
        while (this.pos < this.lines.length) {
          const nl = this.lines[this.pos];
          if (this.empty(nl)) { this.pos++; continue; }
          const nind = this.indent(nl), nt = nl.trim();
          if (nind <= ind || nt.startsWith('- ')) break;
          if (this.hasColon(nt)) {
            const nci = this.colonIdx(nt);
            const nk = nt.slice(0, nci).trim(), nv = nt.slice(nci + 1).trim();
            this.pos++;
            map[nk] = nv === '' ? this.parseNestedMapValue(nind) : this.parseScalar(nv);
          } else break;
        }
        res.push(map);
      } else {
        res.push(this.parseScalar(after));
      }
    }
    return res;
  }

  private parseNestedMapValue(parentIndent: number): YAMLValue {
    const next = this.peekNonEmpty();
    if (next && this.indent(next) > parentIndent) return this.parseValue(this.indent(next));
    return null;
  }

  private parseBlock(baseIndent: number, literal: boolean): string {
    const lines: string[] = [];
    let blockIndent: number | null = null;
    while (this.pos < this.lines.length) {
      const line = this.lines[this.pos], ind = this.indent(line);
      if (line.trim() === '') { if (blockIndent !== null) lines.push(''); this.pos++; continue; }
      if (blockIndent === null) { if (ind <= baseIndent) break; blockIndent = ind; }
      if (ind < blockIndent) break;
      lines.push(line.slice(blockIndent));
      this.pos++;
    }
    return literal ? lines.join('\n') : lines.join(' ').replace(/\s+/g, ' ').trim();
  }

  private parseScalar(v: string): YAMLValue {
    // Remove inline comment
    let sq = false, dq = false;
    for (let i = 0; i < v.length; i++) {
      const c = v[i], p = i > 0 ? v[i-1] : '';
      if (c === "'" && !dq && p !== '\\') sq = !sq;
      else if (c === '"' && !sq && p !== '\\') dq = !dq;
      else if (c === '#' && !sq && !dq && p === ' ') { v = v.slice(0, i-1).trim(); break; }
    }
    if (!v || v === 'null' || v === '~') return null;
    if (['true','yes','on'].includes(v.toLowerCase())) return true;
    if (['false','no','off'].includes(v.toLowerCase())) return false;
    if ((v[0] === '"' && v.slice(-1) === '"') || (v[0] === "'" && v.slice(-1) === "'")) return v.slice(1, -1);
    if (v[0] === '"' || v[0] === "'") throw new Error(`Unclosed quote at line ${this.pos + 1}`);
    if (/^-?\d+$/.test(v)) return parseInt(v, 10);
    if (/^-?\d+\.\d+$/.test(v)) return parseFloat(v);
    return v;
  }

  private peekNonEmpty(): string | null {
    for (let i = this.pos; i < this.lines.length; i++) if (!this.empty(this.lines[i])) return this.lines[i];
    return null;
  }
}

