/**
 * YAML syntax validator using Bun's native YAML.parse().
 */

import type { YamlError } from "./types";

/**
 * Result of parsing YAML content.
 */
export interface ParseResult {
  /** Whether the YAML is syntactically valid */
  valid: boolean;
  /** Array of errors found (empty if valid) */
  errors: YamlError[];
}

/**
 * Parse and validate YAML content for syntax errors.
 * Uses Bun's native YAML.parse() for validation.
 *
 * @param content - The YAML content to validate
 * @param sourceName - Name of the source for error context (optional)
 * @returns Parse result with validity status and any errors
 */
export function parseYaml(content: string, sourceName?: string): ParseResult {
  // Handle empty content - valid YAML
  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  // Handle comments-only content - valid YAML
  const lines = content.split("\n");
  const hasNonCommentContent = lines.some((line) => {
    const trimmed = line.trim();
    return trimmed !== "" && !trimmed.startsWith("#");
  });

  if (!hasNonCommentContent) {
    return { valid: true, errors: [] };
  }

  try {
    // Use Bun's native YAML parser
    // For multi-document YAML, we need to handle each document
    const documents = splitYamlDocuments(content);

    for (const doc of documents) {
      if (doc.content.trim() !== "") {
        YAML.parse(doc.content);
      }
    }

    return { valid: true, errors: [] };
  } catch (error) {
    const yamlError = parseYamlError(error, content);
    return {
      valid: false,
      errors: [yamlError],
    };
  }
}

/**
 * Split YAML content into individual documents.
 * YAML documents are separated by '---' and optionally ended with '...'.
 */
function splitYamlDocuments(
  content: string
): Array<{ content: string; startLine: number }> {
  const lines = content.split("\n");
  const documents: Array<{ content: string; startLine: number }> = [];
  let currentDoc: string[] = [];
  let currentStartLine = 1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "---") {
      // Start of a new document
      if (currentDoc.length > 0) {
        documents.push({
          content: currentDoc.join("\n"),
          startLine: currentStartLine,
        });
      }
      currentDoc = [];
      currentStartLine = i + 2; // Next line after '---'
    } else if (trimmed === "...") {
      // End of current document
      if (currentDoc.length > 0) {
        documents.push({
          content: currentDoc.join("\n"),
          startLine: currentStartLine,
        });
      }
      currentDoc = [];
      currentStartLine = i + 2;
    } else {
      currentDoc.push(line);
    }
  }

  // Add the last document if any content remains
  if (currentDoc.length > 0) {
    documents.push({
      content: currentDoc.join("\n"),
      startLine: currentStartLine,
    });
  }

  // If no documents were found (no separators), treat entire content as one doc
  if (documents.length === 0) {
    documents.push({ content, startLine: 1 });
  }

  return documents;
}

/**
 * Parse a YAML error and extract line/column information.
 */
function parseYamlError(error: unknown, content: string): YamlError {
  const errorMessage =
    error instanceof Error ? error.message : String(error);

  // Try to extract line and column from the error message
  // Bun's YAML parser typically includes position info in the error
  const lineColMatch = errorMessage.match(
    /(?:at line (\d+)|line (\d+)|:(\d+):(\d+))/i
  );
  const columnMatch = errorMessage.match(
    /(?:column (\d+)|col (\d+)|:\d+:(\d+))/i
  );

  let line = 1;
  let column: number | undefined;

  if (lineColMatch) {
    line = parseInt(
      lineColMatch[1] || lineColMatch[2] || lineColMatch[3] || "1",
      10
    );
  }

  if (columnMatch) {
    column = parseInt(
      columnMatch[1] || columnMatch[2] || columnMatch[3] || "1",
      10
    );
  }

  // Extract a snippet of the problematic line
  const lines = content.split("\n");
  const snippet =
    line > 0 && line <= lines.length ? lines[line - 1] : undefined;

  // Clean up the error message
  const cleanMessage = cleanErrorMessage(errorMessage);

  return {
    line,
    column,
    message: cleanMessage,
    snippet,
  };
}

/**
 * Clean up the error message to be more user-friendly.
 */
function cleanErrorMessage(message: string): string {
  // Remove file path prefixes if present
  let cleaned = message.replace(/^.*?:\s*/, "");

  // Capitalize first letter
  if (cleaned.length > 0) {
    cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
  }

  return cleaned;
}

