/**
 * Error and success message formatter for the YAML validator command.
 */

import type { ValidationResult, YamlError } from "./types";

/**
 * Format a success message for a validated file.
 *
 * @param source - The filename or "stdin"
 * @returns Formatted success message
 */
export function formatSuccess(source: string): string {
  return `${source}: OK`;
}

/**
 * Format a failure message for a file with validation errors.
 *
 * @param source - The filename or "stdin"
 * @returns Formatted failure header
 */
export function formatFailure(source: string): string {
  return `${source}: FAILED`;
}

/**
 * Format a single YAML error with line, column, message, and optional snippet.
 *
 * @param error - The YAML error to format
 * @returns Formatted error message lines
 */
export function formatError(error: YamlError): string {
  const lines: string[] = [];

  // Format position info: "  Line X, Column Y: message" or "  Line X: message"
  const position = error.column
    ? `Line ${error.line}, Column ${error.column}`
    : `Line ${error.line}`;
  lines.push(`  ${position}: ${error.message}`);

  // Add snippet with caret if available
  if (error.snippet !== undefined) {
    lines.push(`    > ${error.snippet}`);

    // Add caret pointing to the error position
    if (error.column !== undefined && error.column > 0) {
      // Offset: 4 spaces indent + "> " prefix + (column - 1) spaces
      const caretOffset = 4 + 2 + (error.column - 1);
      lines.push(" ".repeat(caretOffset) + "^");
    }
  }

  return lines.join("\n");
}

/**
 * Format a complete validation result including all errors.
 *
 * @param result - The validation result to format
 * @returns Object with stdout and stderr content
 */
export function formatResult(result: ValidationResult): {
  stdout: string;
  stderr: string;
} {
  if (result.valid) {
    return {
      stdout: formatSuccess(result.source),
      stderr: "",
    };
  }

  const errorLines: string[] = [formatFailure(result.source)];
  for (const error of result.errors) {
    errorLines.push(formatError(error));
  }

  return {
    stdout: "",
    stderr: errorLines.join("\n"),
  };
}

/**
 * Format a batch summary for multiple file validations.
 *
 * @param total - Total number of files validated
 * @param passed - Number of files that passed validation
 * @param failed - Number of files that failed validation
 * @returns Formatted batch summary
 */
export function formatBatchSummary(
  total: number,
  passed: number,
  failed: number
): string {
  return `Validated ${total} files: ${passed} passed, ${failed} failed`;
}

/**
 * Format all validation results for output.
 *
 * @param results - Array of validation results
 * @returns Object with combined stdout and stderr content
 */
export function formatResults(results: ValidationResult[]): {
  stdout: string;
  stderr: string;
} {
  const stdoutLines: string[] = [];
  const stderrLines: string[] = [];

  let passed = 0;
  let failed = 0;

  for (const result of results) {
    const formatted = formatResult(result);
    if (formatted.stdout) {
      stdoutLines.push(formatted.stdout);
    }
    if (formatted.stderr) {
      stderrLines.push(formatted.stderr);
    }

    if (result.valid) {
      passed++;
    } else {
      failed++;
    }
  }

  // Add batch summary if more than one file was validated
  if (results.length > 1) {
    stdoutLines.push(formatBatchSummary(results.length, passed, failed));
  }

  return {
    stdout: stdoutLines.join("\n"),
    stderr: stderrLines.join("\n"),
  };
}

/**
 * Write success/info messages to stdout.
 *
 * @param message - The message to write
 */
export function writeStdout(message: string): void {
  if (message) {
    console.log(message);
  }
}

/**
 * Write error messages to stderr.
 *
 * @param message - The message to write
 */
export function writeStderr(message: string): void {
  if (message) {
    console.error(message);
  }
}

/**
 * Output all validation results to stdout and stderr.
 *
 * @param results - Array of validation results
 */
export function outputResults(results: ValidationResult[]): void {
  const { stdout, stderr } = formatResults(results);
  writeStderr(stderr);
  writeStdout(stdout);
}

/**
 * Validation orchestration for the YAML validator command.
 * Coordinates file reading, stdin handling, and YAML parsing.
 */

import { parseYaml } from "./yaml-parser";
import type { ValidationResult, YamlError } from "./types";

/**
 * Validate YAML content from a file path.
 *
 * @param filePath - Path to the YAML file to validate
 * @returns Validation result with source, validity, and any errors
 */
export async function validateFile(filePath: string): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      return {
        source: filePath,
        valid: false,
        errors: [
          {
            line: 0,
            message: `File not found: ${filePath}`,
          },
        ],
      };
    }

    // Check if the file appears to be binary
    const isBinary = await isFileBinary(file);
    if (isBinary) {
      return {
        source: filePath,
        valid: false,
        errors: [
          {
            line: 0,
            message: "Cannot validate binary file",
          },
        ],
      };
    }

    const content = await file.text();
    const parseResult = parseYaml(content, filePath);

    return {
      source: filePath,
      valid: parseResult.valid,
      errors: parseResult.errors,
    };
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : String(error);
    return {
      source: filePath,
      valid: false,
      errors: [
        {
          line: 0,
          message: `Error reading file: ${errorMessage}`,
        },
      ],
    };
  }
}

/**
 * Validate YAML content from stdin.
 *
 * @returns Validation result with source as "stdin"
 */
export async function validateStdin(): Promise<ValidationResult> {
  try {
    const content = await readStdin();

    if (content === null) {
      return {
        source: "stdin",
        valid: false,
        errors: [
          {
            line: 0,
            message: "No input received from stdin",
          },
        ],
      };
    }

    const parseResult = parseYaml(content, "stdin");

    return {
      source: "stdin",
      valid: parseResult.valid,
      errors: parseResult.errors,
    };
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : String(error);
    return {
      source: "stdin",
      valid: false,
      errors: [
        {
          line: 0,
          message: `Error reading stdin: ${errorMessage}`,
        },
      ],
    };
  }
}

/**
 * Read content from stdin.
 *
 * @returns The stdin content as a string, or null if no input
 */
async function readStdin(): Promise<string | null> {
  const chunks: Uint8Array[] = [];
  const reader = Bun.stdin.stream().getReader();

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        chunks.push(value);
      }
    }
  } finally {
    reader.releaseLock();
  }

  if (chunks.length === 0) {
    return null;
  }

  // Combine chunks and decode as UTF-8
  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const combined = new Uint8Array(totalLength);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.length;
  }

  return new TextDecoder("utf-8").decode(combined);
}

/**
 * Check if a file appears to be binary (non-text).
 * Uses a simple heuristic: checks for null bytes in the first 8KB.
 *
 * @param file - The Bun file object to check
 * @returns True if the file appears to be binary
 */
async function isFileBinary(file: ReturnType<typeof Bun.file>): Promise<boolean> {
  try {
    // Read first 8KB to check for binary content
    const sampleSize = 8192;
    const fileSize = file.size;
    const readSize = Math.min(sampleSize, fileSize);

    if (readSize === 0) {
      return false; // Empty files are not binary
    }

    const buffer = await file.slice(0, readSize).arrayBuffer();
    const bytes = new Uint8Array(buffer);

    // Check for null bytes (common indicator of binary content)
    for (let i = 0; i < bytes.length; i++) {
      if (bytes[i] === 0) {
        return true;
      }
    }

    return false;
  } catch {
    // If we can't read the file, assume it's not binary
    return false;
  }
}

/**
 * Validate multiple YAML files.
 *
 * @param filePaths - Array of file paths to validate
 * @returns Array of validation results
 */
export async function validateFiles(
  filePaths: string[]
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    const result = await validateFile(filePath);
    results.push(result);
  }

  return results;
}

/**
 * Main validation function that orchestrates file and stdin validation.
 *
 * @param filePaths - Array of file paths to validate
 * @param useStdin - Whether to read from stdin
 * @returns Array of validation results
 */
export async function validate(
  filePaths: string[],
  useStdin: boolean
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  // Validate stdin if requested
  if (useStdin) {
    const stdinResult = await validateStdin();
    results.push(stdinResult);
  }

  // Validate files
  if (filePaths.length > 0) {
    const fileResults = await validateFiles(filePaths);
    results.push(...fileResults);
  }

  return results;
}

/**
 * Check if all validation results indicate success.
 *
 * @param results - Array of validation results
 * @returns True if all results are valid
 */
export function allValid(results: ValidationResult[]): boolean {
  return results.every((result) => result.valid);
}

